window.FAQ=(window.FAQ||[]).concat([
 {id:'dgx-001',thema:'doelgroepen',vraag:'Krijgt een starter de startersvrijstelling als de partner ouder is dan de leeftijdsgrens?',antwoord:`De vrijstelling is persoonsgebonden en geldt per verkrijger. De jongere partner kan de vrijstelling krijgen voor het eigen aandeel in de woning. Over het aandeel van de oudere partner is overdrachtsbelasting verschuldigd. Neem dit mee in de berekening van de kosten koper.`,tags:['starters','overdrachtsbelasting','leeftijd','partners'],bron:'Wet op belastingen van rechtsverkeer'},
 {id:'dgx-002',thema:'doelgroepen',vraag:'Wat gebeurt er als een starter de startersvrijstelling al eerder heeft gebruikt?',antwoord:`De startersvrijstelling kan maar één keer per persoon worden gebruikt. Bij een tweede aankoop geldt het verlaagde tarief voor de eigen woning, mits de koper er zelf gaat wonen. Vraag bij de inventarisatie altijd of de klant eerder een woning kocht. Leg het antwoord vast in het dossier.`,tags:['starters','overdrachtsbelasting','inventarisatie'],bron:'Wet op belastingen van rechtsverkeer'},
 {id:'dgx-003',thema:'doelgroepen',vraag:'Welke verklaring tekent een starter voor de vrijstelling overdrachtsbelasting?',antwoord:`De koper verklaart bij de notaris dat de woning als hoofdverblijf zal worden gebruikt. De koper verklaart ook dat de vrijstelling niet eerder is benut. Een onjuiste verklaring kan leiden tot een naheffing. Wijs de klant op het belang van een juiste verklaring.`,tags:['starters','overdrachtsbelasting','notaris'],bron:'Wet op belastingen van rechtsverkeer'},
 {id:'dgx-004',thema:'doelgroepen',vraag:'Kunnen ouders die mee-eigenaar worden ook de startersvrijstelling krijgen?',antwoord:`Nee, meestal niet. De vrijstelling vereist onder meer dat de verkrijger de woning zelf als hoofdverblijf gaat gebruiken. Ouders die er niet wonen, betalen over hun aandeel het algemene tarief. Bespreek dit vooraf, want het beïnvloedt de kosten koper.`,tags:['starters','ouders','mede-eigendom','overdrachtsbelasting'],bron:'Wet op belastingen van rechtsverkeer'},
 {id:'dgx-005',thema:'doelgroepen',vraag:'Welke valkuilen zie je bij een starter met een proeftijd?',antwoord:`Een arbeidsovereenkomst met lopende proeftijd wordt niet door elke geldverstrekker geaccepteerd. Sommige geldverstrekkers accepteren het inkomen als de proeftijd is verstreken of vervalt bij een vast contract. Plan het passeren zo nodig na de proeftijd. Controleer de voorwaarden van de geldverstrekker.`,tags:['starters','proeftijd','inkomen','acceptatie'],bron:''},
 {id:'dgx-006',thema:'doelgroepen',vraag:'Hoe ga je om met een starter die net is afgestudeerd en nog geen loonstrook heeft?',antwoord:`Zonder loonstrook en werkgeversverklaring is het inkomen meestal niet aantoonbaar. Een getekende arbeidsovereenkomst alleen is vaak onvoldoende. Wacht op de eerste loonstrook en de werkgeversverklaring of de uitkomst van een inkomensbepaling. Stem de planning van de aankoop hierop af.`,tags:['starters','inkomensbewijs','werkgeversverklaring'],bron:''},
 {id:'dgx-007',thema:'doelgroepen',vraag:'Telt een dertiende maand of eindejaarsuitkering mee bij een starter?',antwoord:`Een vaste en onvoorwaardelijke eindejaarsuitkering telt in de regel mee. Variabele of voorwaardelijke uitkeringen worden vaak niet of beperkt meegenomen. De werkgeversverklaring moet aangeven of de uitkering structureel is. Controleer de voorwaarden van de geldverstrekker.`,tags:['starters','inkomen','eindejaarsuitkering'],bron:''},
 {id:'dgx-008',thema:'doelgroepen',vraag:'Hoe documenteer je een schenking voor eigen inbreng bij een starter?',antwoord:`Leg vast wie schenkt, welk bedrag en wanneer. Vraag om een schenkingsovereenkomst en een bankafschrift van de overboeking. Controleer of er voorwaarden aan de schenking verbonden zijn. Verwijs voor de aangifte schenkbelasting en het actuele vrijstellingsbedrag naar de Belastingdienst.`,tags:['starters','schenking','dossier','eigen middelen'],bron:'Successiewet 1956'},
 {id:'dgx-010',thema:'doelgroepen',vraag:'Waar let je op bij een lening van ouders aan een starter?',antwoord:`De lening moet zakelijk zijn: een schriftelijke overeenkomst, een zakelijke rente en een aflossingsschema. Voor renteaftrek moet de lening minimaal annuïtair in 360 maanden worden afgelost. De starter moet de gegevens van de lening in de aangifte vermelden. Ouders nemen de vordering op in box 3.`,tags:['starters','familiehypotheek','ouders','aflossingseis'],bron:'Wet IB 2001'},
 {id:'dgx-011',thema:'doelgroepen',vraag:'Wat is een veelgemaakte fout bij een onderhandse lening van ouders?',antwoord:`Vaak ontbreekt een getekende overeenkomst of wordt de rente niet echt betaald. Ook wordt de aflossing niet volgens schema gedaan. Dan kan de Belastingdienst de aftrek weigeren of de lening als schenking zien. Adviseer om alles schriftelijk vast te leggen en betalingen via de bank te laten lopen.`,tags:['starters','familiehypotheek','veelgemaakte fouten'],bron:'Wet IB 2001'},
 {id:'dgx-012',thema:'doelgroepen',vraag:'Hoe beïnvloedt een private lease of autolening de leenruimte van een starter?',antwoord:`Een lopende financiële verplichting verlaagt de maximale hypotheek. Een private leasecontract wordt bij BKR geregistreerd en telt mee in de toetsing. Vraag actief naar zulke verplichtingen, ook als ze niet op het bankafschrift opvallen. Controleer de BKR-registratie en de voorwaarden van de geldverstrekker.`,tags:['starters','BKR','private lease','leencapaciteit'],bron:'BKR'},
 {id:'dgx-013',thema:'doelgroepen',vraag:'Wat moet een starter weten over een studieschuld bij aflossingspauze of draagkracht?',antwoord:`Een tijdelijk lagere termijn bij DUO is niet zonder meer leidend voor de toetsing. Geldverstrekkers volgen de actuele leennormen voor studieschulden. Vraag het actuele DUO-overzicht op en noteer de restschuld en het aflossingsregime. Controleer de voorwaarden van de geldverstrekker.`,tags:['starters','studieschuld','DUO','toetsing'],bron:'DUO'},
 {id:'dgx-014',thema:'doelgroepen',vraag:'Hoeveel extra leenruimte geeft een energiezuinig label bij aankoop?',antwoord:`Volgens de leennormen 2026 hangt de extra ruimte af van het energielabel. Bij label E, F of G is dat 0 euro. Bij C of D 5.000 euro, bij A of B 10.000 euro en bij A+ of A++ 20.000 euro. Bij A+++ 25.000 euro, bij A++++ 30.000 euro en bij A++++ met energieprestatiegarantie 40.000 euro.`,tags:['starters','energielabel','leennormen'],bron:'Nibud'},
 {id:'dgx-015',thema:'doelgroepen',vraag:'Welke extra leenruimte geldt voor verduurzaming bij een starterswoning met label E?',antwoord:`Volgens de leennormen 2026 is bij label E, F of G maximaal 20.000 euro extra mogelijk voor verduurzaming. Bij C of D is dat 15.000 euro en bij A tot en met A++ 10.000 euro. Bij een onbekend label geldt 10.000 euro. Het geld moet echt aan verduurzamingsmaatregelen worden besteed, meestal via een bouwdepot.`,tags:['starters','verduurzaming','energielabel','bouwdepot'],bron:'Nibud'},
 {id:'dgx-016',thema:'doelgroepen',vraag:'Wat geldt voor een alleenstaande starter in de leennormen?',antwoord:`Een alleenstaande krijgt in de leennormen extra leenruimte. Volgens de leennormen 2026 gaat het om 17.000 euro. Dit compenseert deels dat vaste lasten niet worden gedeeld. Controleer of de klant echt alleenstaand is en leg dit vast.`,tags:['starters','alleenstaanden','leennormen'],bron:'Nibud'},
 {id:'dgx-017',thema:'doelgroepen',vraag:'Hoe beoordeel je een starter die samen met een vriend of vriendin koopt?',antwoord:`Beide kopers worden meestal hoofdelijk aansprakelijk voor de hele schuld. Adviseer een notariële overeenkomst over eigendom, inbreng en wat er gebeurt bij vertrek of overlijden. Bespreek ook dat zij geen fiscale partners zijn. Leg de risicobespreking vast in het dossier.`,tags:['starters','mede-eigendom','hoofdelijkheid','samenlevingscontract'],bron:''},
 {id:'dgx-018',thema:'doelgroepen',vraag:'Wanneer is een starter met een opleidingscontract een aandachtspunt?',antwoord:`Een leer-werktraject of traineeship eindigt vaak op een vaste datum. Vraag of er een intentie tot vast dienstverband is en of de werkgeversverklaring die bevat. Zonder intentieverklaring wordt het inkomen vaak als tijdelijk gezien. Controleer de voorwaarden van de geldverstrekker.`,tags:['starters','tijdelijk contract','intentieverklaring'],bron:''},
 {id:'dgx-019',thema:'doelgroepen',vraag:'Kan een starter met een negatief BKR-coderingsverleden een hypotheek krijgen?',antwoord:`Dat hangt af van de aard van de codering en of die is afgelost of hersteld. Veel geldverstrekkers accepteren geen actieve achterstandscodering. Vraag een BKR-inzage op en bespreek de uitkomst open met de klant. Leg de afweging vast in het dossier.`,tags:['starters','BKR','acceptatie'],bron:'BKR'},
 {id:'dgx-020',thema:'doelgroepen',vraag:'Hoe bespreek je de rentevaste periode met een starter?',antwoord:`Een starter heeft vaak weinig buffer om een rentestijging op te vangen. Weeg de zekerheid van een lange rentevaste periode af tegen de kosten. Toets of de woonlasten ook na afloop van de periode betaalbaar blijven. Leg de keuze en de motivatie vast.`,tags:['starters','rentevaste periode','risico'],bron:''},
 {id:'dgx-021',thema:'doelgroepen',vraag:'Welke rol speelt een buffer in de financiële planning van een starter?',antwoord:`Na de aankoop is de spaarbuffer vaak klein. Onverwachte kosten zoals onderhoud of een defecte installatie kunnen dan problemen geven. Bespreek een minimale buffer en stem de eigen inbreng hierop af. Leg de afweging tussen inbreng en buffer vast.`,tags:['starters','buffer','financiële planning'],bron:''},
 {id:'dgx-022',thema:'doelgroepen',vraag:'Waarop let je bij een starter die een nieuwbouwwoning koopt?',antwoord:`Bij nieuwbouw lopen er bouwrente en dubbele lasten tijdens de bouw. De woning kan tot drie jaar vooruit al fiscaal eigen woning zijn als de klant er naar verwachting gaat wonen. Vraag naar de opleverdatum en de huurlasten tot die tijd. Leg de berekening van de dubbele lasten vast.`,tags:['starters','nieuwbouw','bouwrente','dubbele lasten'],bron:'Wet IB 2001'},
 {id:'dgx-023',thema:'doelgroepen',vraag:'Hoe wordt een starter met twee banen getoetst?',antwoord:`Inkomen uit meerdere dienstverbanden telt in de regel mee als het voldoende bestendig is. Elk dienstverband wordt apart beoordeeld op contractvorm en duur. Vraag voor elke werkgever een werkgeversverklaring of gebruik een inkomensbepaling via UWV-gegevens. Controleer de voorwaarden van de geldverstrekker.`,tags:['starters','meerdere werkgevers','inkomen'],bron:''},
 {id:'dgx-024',thema:'doelgroepen',vraag:'Mag een starter de overdrachtsbelasting meefinancieren als er geen vrijstelling is?',antwoord:`Overdrachtsbelasting valt onder kosten koper. Kosten koper kunnen in de regel niet worden meegefinancierd boven de maximale loan-to-value. Daardoor moet de starter deze kosten meestal uit eigen middelen betalen. Toets vooraf of de klant voldoende eigen geld heeft.`,tags:['starters','kosten koper','LTV','eigen middelen'],bron:'Tijdelijke regeling hypothecair krediet'},
 {id:'dgx-025',thema:'doelgroepen',vraag:'Welke gegevens leg je extra vast bij een starter zonder eigen geld?',antwoord:`Leg vast hoe de kosten koper worden betaald en waar het geld vandaan komt. Noteer welke buffer overblijft na aankoop. Beschrijf de risico's van een hoge financiering ten opzichte van de woningwaarde. Laat de klant bevestigen dat de risico's zijn besproken.`,tags:['starters','dossier','eigen middelen','risico'],bron:''},
 {id:'dgx-026',thema:'doelgroepen',vraag:'Wat verandert er als een doorstromer de oude woning nog niet heeft verkocht?',antwoord:`De klant heeft tijdelijk twee woningen en mogelijk twee hypotheken. De oude woning blijft maximaal drie jaar fiscaal eigen woning als die leeg staat en te koop staat. Toets of de dubbele lasten draagbaar zijn. Bespreek een scenario waarin de verkoop langer duurt.`,tags:['doorstromers','dubbele lasten','verkoop'],bron:'Wet IB 2001'},
 {id:'dgx-027',thema:'doelgroepen',vraag:'Wanneer ontstaat een eigenwoningreserve bij een doorstromer?',antwoord:`Een eigenwoningreserve ontstaat als de verkoopopbrengst na kosten hoger is dan de eigenwoningschuld. De reserve moet in de nieuwe woning worden gestoken om renteaftrek niet te beperken. De eigenwoningreserve vervalt na drie jaar. Bereken de reserve en leg de berekening vast.`,tags:['doorstromers','eigenwoningreserve','bijleenregeling'],bron:'Wet IB 2001'},
 {id:'dgx-028',thema:'doelgroepen',vraag:'Hoe reken je de eigenwoningreserve globaal uit?',antwoord:`Neem de verkoopprijs en trek de verkoopkosten af. Trek daarna de eigenwoningschuld af die op de oude woning rust. Het positieve verschil is de eigenwoningreserve. Een eerdere reserve die nog niet is vervallen, telt ook mee.`,tags:['doorstromers','eigenwoningreserve','rekenvoorbeeld'],bron:'Wet IB 2001'},
 {id:'dgx-029',thema:'doelgroepen',vraag:'Welke kosten mag een doorstromer aftrekken van de verkoopprijs bij de eigenwoningreserve?',antwoord:`Alleen kosten die direct met de verkoop samenhangen, zoals makelaarskosten en kosten van verkoopadvertenties. Boetes voor het aflossen van de hypotheek horen hier niet bij. Vraag de nota van de makelaar op. Leg de gebruikte kosten vast in het dossier.`,tags:['doorstromers','eigenwoningreserve','verkoopkosten'],bron:'Belastingdienst'},
 {id:'dgx-030',thema:'doelgroepen',vraag:'Wat gebeurt met de eigenwoningreserve als de klant eerst gaat huren?',antwoord:`De eigenwoningreserve blijft drie jaar bestaan, ook als de klant tussentijds huurt. Koopt de klant binnen die termijn een nieuwe woning, dan vermindert de reserve de aftrekbare schuld. Na drie jaar vervalt de reserve. Wijs de klant op deze termijn en noteer de verkoopdatum.`,tags:['doorstromers','eigenwoningreserve','huren'],bron:'Wet IB 2001'},
 {id:'dgx-031',thema:'doelgroepen',vraag:'Welke fout zie je vaak bij de berekening van de bijleenregeling?',antwoord:`Men vergeet dat er al een eigenwoningreserve uit een eerdere verkoop bestaat. Ook wordt de oude hypotheekschuld soms verkeerd overgenomen. Gebruik de stukken van de oude hypotheek en de jaaropgave. Leg de berekening en bronnen vast in het dossier.`,tags:['doorstromers','bijleenregeling','veelgemaakte fouten'],bron:'Wet IB 2001'},
 {id:'dgx-032',thema:'doelgroepen',vraag:'Wat is het verschil tussen meenemen en oversluiten bij verhuizing?',antwoord:`Bij meenemen wordt de bestaande lening met dezelfde voorwaarden en rente naar de nieuwe woning verhuisd. Bij oversluiten wordt een nieuwe lening afgesloten, soms met een boete op de oude lening. Of meenemen kan, staat in de voorwaarden van de geldverstrekker. Vergelijk beide routes en leg de afweging vast.`,tags:['doorstromers','meeneemregeling','oversluiten'],bron:''},
 {id:'dgx-033',thema:'doelgroepen',vraag:'Behoudt een doorstromer het overgangsrecht van een oude hypotheek?',antwoord:`Een eigenwoningschuld van voor 2013 valt onder het overgangsrecht. Dit kan behouden blijven bij verhuizing, mits aan de wettelijke voorwaarden en termijnen is voldaan. Een nieuwe extra lening valt onder de aflossingseis. Leg per leningdeel vast welk fiscaal regime geldt.`,tags:['doorstromers','overgangsrecht','aflossingseis'],bron:'Wet IB 2001'},
 {id:'dgx-034',thema:'doelgroepen',vraag:'Hoe splits je een nieuwe hypotheek bij een doorstromer met deels oud regime?',antwoord:`Maak een deel met de meegenomen bestaande eigenwoningschuld onder overgangsrecht. Maak een apart deel voor de extra lening dat minimaal annuïtair in 360 maanden wordt afgelost. Zo blijft het fiscale onderscheid zichtbaar. Leg de splitsing vast in het advies.`,tags:['doorstromers','leningdelen','overgangsrecht','aflossingseis'],bron:'Wet IB 2001'},
 {id:'dgx-035',thema:'doelgroepen',vraag:'Wat is een veelgemaakte fout bij de overbruggingslening?',antwoord:`De overbrugging wordt gebaseerd op een te optimistische verkoopprijs. Als de woning minder opbrengt, ontstaat een tekort. Gebruik een voorzichtige waarde, bijvoorbeeld op basis van een recent taxatierapport. Bespreek wat er gebeurt als de verkoop tegenvalt.`,tags:['doorstromers','overbrugging','taxatie'],bron:''},
 {id:'dgx-036',thema:'doelgroepen',vraag:'Is rente over een overbruggingslening aftrekbaar?',antwoord:`Een overbruggingslening voor de aankoop van de nieuwe woning kan eigenwoningschuld zijn. Dan is de rente in principe aftrekbaar, mits de lening voldoet aan de fiscale voorwaarden. Let op de samenloop met de bijleenregeling. Controleer de situatie op basis van de actuele regels van de Belastingdienst.`,tags:['doorstromers','overbrugging','renteaftrek'],bron:'Wet IB 2001'},
 {id:'dgx-037',thema:'doelgroepen',vraag:'Hoe ga je om met een doorstromer die een restschuld heeft na verkoop?',antwoord:`Bij verkoop met verlies kan de klant een restschuld overhouden. Voor restschulden ontstaan tussen 29 oktober 2012 en 31 december 2017 is de rente maximaal 15 jaar aftrekbaar. Een restschuld kan soms worden meegefinancierd, afhankelijk van de geldverstrekker en eventuele NHG-regels. Leg de financieringsopbouw en de fiscale status vast.`,tags:['doorstromers','restschuld','renteaftrek'],bron:'Wet IB 2001'},
 {id:'dgx-038',thema:'doelgroepen',vraag:'Welke rol speelt de koopovereenkomst van de oude woning bij een doorstromer?',antwoord:`Een getekende koopovereenkomst van de oude woning geeft zekerheid over de opbrengst. Let op ontbindende voorwaarden, zoals een financieringsvoorbehoud van de koper. Zolang die gelden, is de verkoop niet definitief. Stem de overbrugging en het passeren daarop af.`,tags:['doorstromers','koopovereenkomst','voorbehoud'],bron:''},
 {id:'dgx-039',thema:'doelgroepen',vraag:'Wanneer is een doorstromer gebaat bij een dubbele-lastenberekening per maand?',antwoord:`Altijd als er tijdelijk twee woningen zijn of bij nieuwbouw met bouwrente. Een maandoverzicht maakt duidelijk hoe lang de buffer volstaat. Neem rente, aflossing, verzekeringen, energie en gemeentelijke lasten mee. Leg het overzicht vast in het dossier.`,tags:['doorstromers','dubbele lasten','buffer'],bron:''},
 {id:'dgx-040',thema:'doelgroepen',vraag:'Wat als een doorstromer de oude woning gaat verhuren in plaats van verkopen?',antwoord:`Dan is de oude woning geen eigen woning meer en valt die in box 3. De schuld op die woning is dan geen eigenwoningschuld meer. Daarnaast moet er toestemming van de geldverstrekker zijn voor verhuur. Bespreek ook de gevolgen voor de bijleenregeling en leg dit vast.`,tags:['doorstromers','verhuur','box 3'],bron:'Wet IB 2001'},
 {id:'dgx-041',thema:'doelgroepen',vraag:'Hoe beïnvloedt een boete voor vervroegd aflossen het advies van een doorstromer?',antwoord:`Bij verkoop van de woning is de boete vaak niet verschuldigd, maar dat hangt af van de voorwaarden. Bij oversluiten zonder verhuizing kan wel een boete gelden. Vraag de berekening van de geldverstrekker op. Leg vast hoe de boete is meegenomen in de vergelijking.`,tags:['doorstromers','boete','oversluiten'],bron:''},
 {id:'dgx-042',thema:'doelgroepen',vraag:'Waar let je op bij een doorstromer met een aflossingsvrij deel van voor 2013?',antwoord:`Dit deel kan onder overgangsrecht blijven bestaan als het wordt meegenomen. Bij verhoging boven de bestaande schuld geldt de aflossingseis voor het extra deel. Bespreek ook of aflossingsvrij verantwoord blijft bij pensionering. Leg de afweging vast.`,tags:['doorstromers','aflossingsvrij','overgangsrecht'],bron:'Wet IB 2001'},
 {id:'dgx-043',thema:'doelgroepen',vraag:'Hoe toets je de overwaarde van een doorstromer als eigen middelen?',antwoord:`Overwaarde is pas beschikbaar na de daadwerkelijke verkoop. Vóór verkoop telt die alleen mee via een overbruggingslening. Gebruik een voorzichtige schatting van de verkoopprijs. Houd rekening met de bijleenregeling bij het bepalen van de aftrekbare schuld.`,tags:['doorstromers','overwaarde','eigen middelen'],bron:''},
 {id:'dgx-044',thema:'doelgroepen',vraag:'Wat moet je vastleggen bij een doorstromer die nog geen verkoopprijs kent?',antwoord:`Leg de gebruikte waardering vast, zoals een taxatie of waardebepaling. Noteer het scenario bij een lagere opbrengst. Beschrijf hoe lang de klant dubbele lasten kan dragen. Laat de klant de uitgangspunten bevestigen.`,tags:['doorstromers','dossier','scenario'],bron:''},
 {id:'dgx-045',thema:'doelgroepen',vraag:'Wat is het verschil tussen een vaste en een open overbruggingslening?',antwoord:`Bij een vaste overbrugging is de oude woning al verkocht met een getekende koopovereenkomst. Bij een open overbrugging is er nog geen koper. Een open overbrugging heeft meer risico en wordt niet door elke geldverstrekker geaccepteerd. Controleer de voorwaarden van de geldverstrekker.`,tags:['doorstromers','overbrugging','risico'],bron:''},
 {id:'dgx-046',thema:'doelgroepen',vraag:'Hoe werkt de energielabel-leenruimte voor een doorstromer?',antwoord:`Dezelfde leennormen gelden voor starters en doorstromers. De extra ruimte hangt af van het energielabel van de nieuwe woning. Bij label C of D is dat volgens de leennormen 2026 5.000 euro en bij A of B 10.000 euro. Gebruik het definitieve label van de woning bij de toetsing.`,tags:['doorstromers','energielabel','leennormen'],bron:'Nibud'},
 {id:'dgx-047',thema:'doelgroepen',vraag:'Kan een doorstromer de oude woning tijdelijk aan familie laten bewonen?',antwoord:`Dan staat de woning niet meer leeg en te koop. De fiscale verlenging van drie jaar voor een leegstaande woning is dan niet van toepassing. De woning valt dan in de regel in box 3. Bespreek dit en controleer de toestemming van de geldverstrekker.`,tags:['doorstromers','leegstand','box 3'],bron:'Wet IB 2001'},
 {id:'dgx-048',thema:'doelgroepen',vraag:'Hoe ga je om met een doorstromer van wie het inkomen is gedaald sinds de vorige hypotheek?',antwoord:`De nieuwe aanvraag wordt getoetst op het huidige inkomen en de actuele normen. De klant kan daardoor minder lenen dan bij de vorige aankoop. Bespreek dit vroeg in het traject. Bekijk of meenemen van de bestaande lening een optie is volgens de voorwaarden.`,tags:['doorstromers','inkomensdaling','toetsing'],bron:''},
 {id:'dgx-049',thema:'doelgroepen',vraag:'Wat betekent de koopakte voor de verhuisregeling van de lening?',antwoord:`Veel meeneemregelingen vereisen dat de nieuwe woning binnen een bepaalde termijn wordt gekocht. Het moment van passeren is dan bepalend. Controleer de termijn in de voorwaarden van de geldverstrekker. Stem de planning van koop en verkoop daarop af.`,tags:['doorstromers','meeneemregeling','termijn'],bron:''},
 {id:'dgx-050',thema:'doelgroepen',vraag:'Welk risico loopt een doorstromer met NHG op de oude woning?',antwoord:`Bij gedwongen verkoop kan NHG een rol spelen bij een restschuld, maar alleen onder strikte voorwaarden. Vrijwillige verkoop met verlies valt daar niet zomaar onder. Raadpleeg de actuele voorwaarden van NHG. Leg vast welke afspraken zijn gemaakt.`,tags:['doorstromers','NHG','restschuld'],bron:'NHG'},
 {id:'dgx-051',thema:'doelgroepen',vraag:'Wanneer houd je bij een senior rekening met het inkomen na pensionering?',antwoord:`Volgens de gedragscode toets je doorgaans ook op het pensioeninkomen als de AOW-leeftijd binnen tien jaar wordt bereikt. Gebruik daarvoor een actueel pensioenoverzicht en de AOW-gegevens. Is de last na pensionering niet draagbaar, dan moet je dat motiveren of de financiering aanpassen. Leg de toetsing en de uitkomst vast.`,tags:['senioren','pensioen','toetsing','gedragscode'],bron:'Gedragscode Hypothecaire Financieringen'},
 {id:'dgx-052',thema:'doelgroepen',vraag:'Hoe ga je om met een AOW-gat bij een senior?',antwoord:`Een AOW-gat ontstaat als iemand niet in alle opbouwjaren in Nederland woonde of werkte. Het AOW-inkomen is dan lager dan het volledige bedrag. Vraag het actuele overzicht bij de SVB op. Gebruik het werkelijke verwachte AOW-bedrag in de toetsing.`,tags:['senioren','AOW','buitenland','toetsing'],bron:'SVB'},
 {id:'dgx-053',thema:'doelgroepen',vraag:'Waarom moet je bij een senior ook het inkomen van de langstlevende toetsen?',antwoord:`Na overlijden van een partner daalt het inkomen vaak sterk. Het nabestaandenpensioen kan lager zijn dan verwacht of ontbreken. Bereken of de langstlevende de woonlasten kan dragen. Bespreek oplossingen zoals een ORV of aflossing en leg de afweging vast.`,tags:['senioren','langstlevende','nabestaandenpensioen','risico'],bron:''},
 {id:'dgx-054',thema:'doelgroepen',vraag:'Wat moet je vastleggen als je bij een senior afwijkt via explain?',antwoord:`Beschrijf waarom de financiering ondanks de afwijking verantwoord is. Noem de concrete feiten, zoals vermogen, lage woonlasten of een geplande verkoop. Leg ook vast welke risico's zijn besproken. Een algemene motivering zonder cijfers is onvoldoende.`,tags:['senioren','explain','dossier'],bron:'Gedragscode Hypothecaire Financieringen'},
 {id:'dgx-055',thema:'doelgroepen',vraag:'Kan vermogen bij een senior als inkomen worden meegenomen?',antwoord:`Sommige geldverstrekkers rekenen vrij beschikbaar vermogen om naar een fictief inkomen. De methode en voorwaarden verschillen per geldverstrekker. Controleer of het vermogen echt beschikbaar is en niet nodig is als buffer. Controleer de voorwaarden van de geldverstrekker.`,tags:['senioren','vermogen','inkomen'],bron:''},
 {id:'dgx-056',thema:'doelgroepen',vraag:'Hoe telt een tijdelijke lijfrente-uitkering mee bij een senior?',antwoord:`Een tijdelijke uitkering telt alleen mee zolang die loopt. Voor de periode daarna moet de toetsing aansluiten op het blijvende inkomen. Vraag de polis en het uitkeringsoverzicht op. Leg vast hoe de einddatum in de toetsing is verwerkt.`,tags:['senioren','lijfrente','inkomen'],bron:''},
 {id:'dgx-057',thema:'doelgroepen',vraag:'Wat is het risico van een opeethypotheek voor een senior?',antwoord:`Bij een opeethypotheek wordt rente vaak bijgeschreven bij de schuld. De schuld groeit daardoor met rente op rente. De overwaarde kan op termijn sterk afnemen. Bespreek het effect op erfgenamen en op een latere verhuizing naar zorg.`,tags:['senioren','opeethypotheek','overwaarde','risico'],bron:''},
 {id:'dgx-058',thema:'doelgroepen',vraag:'Is rente op geleend geld voor consumptie bij een senior aftrekbaar?',antwoord:`Nee. Alleen schuld voor aankoop, verbetering of onderhoud van de eigen woning kan eigenwoningschuld zijn. Een lening voor consumptie of een schenking aan kinderen valt in box 3. Maak dit onderscheid duidelijk in het advies. Leg de bestedingsdoelen vast.`,tags:['senioren','renteaftrek','box 3','consumptief'],bron:'Wet IB 2001'},
 {id:'dgx-059',thema:'doelgroepen',vraag:'Wanneer eindigt de renteaftrek op hypotheken die al in 2001 bestonden?',antwoord:`Voor schulden die op 1 januari 2001 al bestonden, begon de dertigjaarstermijn op die datum. De aftrek eindigt daardoor uiterlijk eind 2030. Bij senioren met oude leningen is dit een belangrijk aandachtspunt. Bereken de netto lasten na het einde van de aftrek.`,tags:['senioren','renteaftrek','dertig jaar','overgangsrecht'],bron:'Wet IB 2001'},
 {id:'dgx-060',thema:'doelgroepen',vraag:'Wat betekent de afbouw van de Wet Hillen voor een senior met een afgeloste woning?',antwoord:`Bij een geringe of geen eigenwoningschuld gold de aftrek wegens geen of geringe eigenwoningschuld. Die aftrek wordt vanaf 2019 in 30 jaar afgebouwd. Het netto belastbare eigenwoningforfait stijgt daardoor geleidelijk. Neem dit mee in de netto lastenberekening.`,tags:['senioren','Wet Hillen','eigenwoningforfait'],bron:'Wet IB 2001'},
 {id:'dgx-061',thema:'doelgroepen',vraag:'Wat gebeurt er als de looptijd van een aflossingsvrije hypotheek afloopt bij een senior?',antwoord:`Aan het einde van de looptijd moet de schuld in principe worden afgelost. Is dat niet mogelijk, dan is herfinanciering nodig, soms bij een andere geldverstrekker. Begin tijdig met het in kaart brengen van inkomen en waarde. Controleer de voorwaarden van de huidige geldverstrekker.`,tags:['senioren','aflossingsvrij','einde looptijd','herfinanciering'],bron:''},
 {id:'dgx-062',thema:'doelgroepen',vraag:'Hoe beoordeel je een kapitaalverzekering eigen woning bij een senior?',antwoord:`Een kapitaalverzekering eigen woning kan onder voorwaarden belastingvrij uitkeren. Denk aan een minimale premieduur en de bandbreedte van de premies. Controleer of de polis nog aan alle voorwaarden voldoet. Wijzigingen in de polis kunnen fiscale gevolgen hebben.`,tags:['senioren','KEW','overgangsrecht','polis'],bron:'Wet IB 2001'},
 {id:'dgx-063',thema:'doelgroepen',vraag:'Wat gebeurt er met de fiscale woning als een senior naar een verpleeghuis gaat?',antwoord:`Als de woning leeg komt te staan en te koop wordt gezet, kan die nog maximaal drie jaar eigen woning blijven. Blijft de partner er wonen, dan blijft de woning eigen woning. Wordt de woning verhuurd of door anderen bewoond, dan valt die in box 3. Leg de situatie en data vast.`,tags:['senioren','zorg','leegstand','eigen woning'],bron:'Wet IB 2001'},
 {id:'dgx-064',thema:'doelgroepen',vraag:'Waar let je op bij financiering van een mantelzorgwoning op het perceel?',antwoord:`Controleer of de bouw is toegestaan volgens de gemeentelijke regels. Vraag of de geldverstrekker de extra woonruimte accepteert en hoe die wordt getaxeerd. Bespreek de gevolgen bij verkoop en na overlijden. Controleer de voorwaarden van de geldverstrekker.`,tags:['senioren','mantelzorg','taxatie','verbouwing'],bron:''},
 {id:'dgx-065',thema:'doelgroepen',vraag:'Hoe ga je om met een senior die verhuist naar een kleinere woning?',antwoord:`De nieuwe woning is vaak goedkoper, waardoor overwaarde vrijkomt. Houd rekening met de bijleenregeling als de klant later weer een duurdere woning koopt. Bespreek of de overwaarde wordt afgelost, gespaard of geschonken. Leg de bestemming van de overwaarde vast.`,tags:['senioren','verhuizing','overwaarde','eigenwoningreserve'],bron:'Wet IB 2001'},
 {id:'dgx-066',thema:'doelgroepen',vraag:'Welke rol speelt een veel jongere partner bij een senior?',antwoord:`De jongere partner heeft vaak nog inkomen uit werk, maar ook een langere looptijd. Toets het huishoudinkomen op meerdere momenten: nu, bij pensioen van de oudste en bij overlijden. Bespreek de positie van de jongere partner na overlijden. Leg de scenario's vast.`,tags:['senioren','leeftijdsverschil','scenario'],bron:''},
 {id:'dgx-067',thema:'doelgroepen',vraag:'Hoe verwerk je een hoog-laagconstructie in het pensioen bij een senior?',antwoord:`Bij een hoog-laagconstructie is het pensioen eerst hoger en later lager. Toets op het lagere, blijvende pensioen. Vraag het besluit en het overzicht van de pensioenuitvoerder op. Leg vast hoe het lagere bedrag is meegenomen.`,tags:['senioren','pensioen','hoog-laag'],bron:''},
 {id:'dgx-068',thema:'doelgroepen',vraag:'Welke bron gebruik je voor pensioeninkomen bij een senior?',antwoord:`Gebruik het actuele overzicht van de pensioenuitvoerder of mijnpensioenoverzicht.nl. Let op dat bedragen kunnen wijzigen door de overgang naar het nieuwe pensioenstelsel. Vraag bij twijfel een recent uniform pensioenoverzicht op. Bewaar het gebruikte overzicht in het dossier.`,tags:['senioren','pensioenoverzicht','bronnen'],bron:'Pensioenregister'},
 {id:'dgx-069',thema:'doelgroepen',vraag:'Mag een senior lenen om te schenken aan kinderen?',antwoord:`Dat kan, maar het geleende geld is dan geen eigenwoningschuld. De rente is daardoor niet aftrekbaar. Bespreek de gevolgen voor de draagkracht en voor de langstlevende. Leg vast dat de klant de risico's begrijpt.`,tags:['senioren','schenking','box 3','kinderen'],bron:'Wet IB 2001'},
 {id:'dgx-070',thema:'doelgroepen',vraag:'Hoe bespreek je toekomstige zorgkosten met een senior?',antwoord:`Zorgkosten kunnen het besteedbaar inkomen later verlagen. Denk aan eigen bijdragen, aanpassingen aan de woning en hulp in huis. Bespreek dit als scenario en niet als vaste rekenpost. Leg vast dat het onderwerp is besproken.`,tags:['senioren','zorg','scenario','budget'],bron:''},
 {id:'dgx-071',thema:'doelgroepen',vraag:'Wat zijn aandachtspunten bij een senior met pensioen uit het buitenland?',antwoord:`Vraag naar de valuta, de uitkeringsduur en de belastingheffing. Koersschommelingen kunnen het inkomen in euro verlagen. Niet elke geldverstrekker accepteert buitenlands pensioen volledig. Controleer de voorwaarden van de geldverstrekker.`,tags:['senioren','buitenlands pensioen','valuta'],bron:''},
 {id:'dgx-072',thema:'doelgroepen',vraag:'Is een ORV nog nodig bij een senior met een lage hypotheek?',antwoord:`Dat hangt af van de draagkracht van de langstlevende. Bij voldoende nabestaandenpensioen of vermogen kan een ORV overbodig zijn. Maak een berekening per scenario. Leg de conclusie en de motivering vast.`,tags:['senioren','ORV','langstlevende'],bron:''},
 {id:'dgx-073',thema:'doelgroepen',vraag:'Wat is een veelgemaakte fout bij het toetsen van senioren?',antwoord:`Men toetst alleen op het huidige inkomen en vergeet de inkomensdaling bij pensionering. Ook wordt het einde van de renteaftrek op oude leningen vaak niet meegenomen. Gebruik een tijdlijn met de belangrijke momenten. Leg deze tijdlijn vast in het dossier.`,tags:['senioren','veelgemaakte fouten','tijdlijn'],bron:''},
 {id:'dgx-074',thema:'doelgroepen',vraag:'Hoe vergelijk je verzilveren met verkopen en huren voor een senior?',antwoord:`Bij verzilveren blijft de klant eigenaar en gaat de schuld omhoog. Bij verkopen en huren komt het vermogen vrij, maar de klant betaalt huur en verliest eigendom. Vergelijk de netto lasten en de vermogensontwikkeling. Leg de afweging en de voorkeur van de klant vast.`,tags:['senioren','verzilveren','huren','vergelijking'],bron:''},
 {id:'dgx-075',thema:'doelgroepen',vraag:'Waar let je op bij een senior die een woning koopt met een kind als mede-eigenaar?',antwoord:`Het kind wordt mede-eigenaar en vaak ook schuldenaar. Bespreek wat er gebeurt bij overlijden, scheiding van het kind of verkoop. Leg afspraken notarieel vast. Controleer de voorwaarden van de geldverstrekker over mede-eigendom.`,tags:['senioren','kinderen','mede-eigendom'],bron:''},
 {id:'dgx-076',thema:'doelgroepen',vraag:'Kunnen ex-partners in het jaar van scheiding nog fiscale partners zijn?',antwoord:`Ja, onder voorwaarden kunnen zij kiezen om het hele jaar fiscale partners te blijven. Dat kan als zij een deel van het jaar fiscale partners waren. Dit kan voordelig zijn voor het verdelen van aftrekposten. Verwijs voor de details naar de Belastingdienst.`,tags:['scheiding','fiscaal partnerschap','aangifte'],bron:'Wet IB 2001'},
 {id:'dgx-077',thema:'doelgroepen',vraag:'Hoe lang kan de woning eigen woning blijven voor de vertrekkende partner?',antwoord:`De woning blijft maximaal twee jaar eigen woning voor de vertrekkende partner. Voorwaarde is dat de achterblijvende ex-partner er blijft wonen. Daarna valt het aandeel van de vertrekkende partner in box 3. Leg de vertrekdatum vast.`,tags:['scheiding','eigen woning','twee jaar'],bron:'Wet IB 2001'},
 {id:'dgx-078',thema:'doelgroepen',vraag:'Valt een extra lening om de ex-partner uit te kopen onder de aflossingseis?',antwoord:`Ja, een lening voor de aankoop van het aandeel van de ex-partner is nieuwe eigenwoningschuld. Die moet minimaal annuïtair in 360 maanden worden afgelost voor renteaftrek. Het eigen deel van de bestaande schuld kan onder overgangsrecht blijven. Splits de leningdelen en leg dit vast.`,tags:['scheiding','uitkoop','aflossingseis'],bron:'Wet IB 2001'},
 {id:'dgx-079',thema:'doelgroepen',vraag:'Kan de overnemende partner het overgangsrecht van de ex-partner voortzetten?',antwoord:`Bij overname van het aandeel van de ex-partner kan onder voorwaarden het overgangsrecht voor het overgenomen deel van de schuld behouden blijven. De exacte voorwaarden zijn technisch. Controleer de situatie aan de hand van de wet of laat dit fiscaal toetsen. Leg per leningdeel het regime vast.`,tags:['scheiding','overgangsrecht','overname'],bron:'Wet IB 2001'},
 {id:'dgx-080',thema:'doelgroepen',vraag:'Welke peildatum gebruik je voor de waarde van de woning bij scheiding?',antwoord:`Partners spreken de peildatum meestal af in het convenant. Gebruik een recent taxatierapport als basis voor de overname. Een verouderde waarde kan tot onenigheid leiden. Leg de gebruikte waarde en de datum vast.`,tags:['scheiding','waardering','taxatie','convenant'],bron:''},
 {id:'dgx-081',thema:'doelgroepen',vraag:'Wat is het verschil tussen gemeenschap van goederen en beperkte gemeenschap bij scheiding?',antwoord:`Voor huwelijken vanaf 1 januari 2018 geldt standaard de beperkte gemeenschap van goederen. Bezittingen van voor het huwelijk blijven dan in principe privé. Bij oudere huwelijken geldt vaak de algehele gemeenschap. Vraag naar de huwelijksdatum en eventuele huwelijkse voorwaarden.`,tags:['scheiding','huwelijksgoederenrecht','vermogen'],bron:'Burgerlijk Wetboek'},
 {id:'dgx-082',thema:'doelgroepen',vraag:'Waarom is een ouderschapsplan relevant voor de hypotheekadviseur?',antwoord:`Bij minderjarige kinderen is een ouderschapsplan verplicht bij de scheiding. Het plan bevat onder meer de zorgverdeling en de kosten van de kinderen. Dat beïnvloedt de woonwens en de betaalbaarheid. Vraag het plan op als onderdeel van het dossier.`,tags:['scheiding','ouderschapsplan','kinderen'],bron:'Burgerlijk Wetboek'},
 {id:'dgx-083',thema:'doelgroepen',vraag:'Wanneer duurt partneralimentatie langer dan vijf jaar?',antwoord:`Sinds 2020 is de hoofdregel maximaal vijf jaar. Bij kinderen jonger dan twaalf loopt de alimentatie door tot het jongste kind twaalf wordt. Er gelden ook uitzonderingen bij lange huwelijken. Controleer de datum in het convenant of de beschikking.`,tags:['scheiding','partneralimentatie','duur'],bron:'Wet limitering partneralimentatie'},
 {id:'dgx-084',thema:'doelgroepen',vraag:'Is betaalde kinderalimentatie fiscaal aftrekbaar?',antwoord:`Nee, kinderalimentatie is niet aftrekbaar. Ontvangen kinderalimentatie is ook niet belast. Partneralimentatie is wel aftrekbaar voor de betaler en belast voor de ontvanger. Houd dit verschil aan bij de netto lastenberekening.`,tags:['scheiding','kinderalimentatie','fiscaal'],bron:'Wet IB 2001'},
 {id:'dgx-085',thema:'doelgroepen',vraag:'Hoe verdeel je pensioen bij scheiding?',antwoord:`Het tijdens het huwelijk opgebouwde ouderdomspensioen wordt in de regel verevend. De melding moet binnen de wettelijke termijn bij de pensioenuitvoerder worden gedaan. Partners kunnen in het convenant anders afspreken. Wijs de klant op deze termijn.`,tags:['scheiding','pensioenverevening','termijn'],bron:'Wet verevening pensioenrechten bij scheiding'},
 {id:'dgx-086',thema:'doelgroepen',vraag:'Welk risico lopen ex-partners als zij de woning onverdeeld laten?',antwoord:`Beide blijven eigenaar en meestal hoofdelijk aansprakelijk. Als een van beiden niet meer betaalt, kan de geldverstrekker de ander aanspreken. Ook kan de vertrekkende partner moeilijker een nieuwe woning financieren. Adviseer om afspraken vast te leggen en een termijn voor verdeling te kiezen.`,tags:['scheiding','onverdeeldheid','hoofdelijkheid'],bron:''},
 {id:'dgx-087',thema:'doelgroepen',vraag:'Kunnen geregistreerde partners zonder rechter uit elkaar gaan?',antwoord:`Ja, als er geen minderjarige kinderen zijn, kan een geregistreerd partnerschap buiten de rechter om worden beëindigd. Dat gebeurt met een overeenkomst en tussenkomst van advocaten of notaris. Bij kinderen is een gang naar de rechter nodig. Vraag welke route de klant volgt.`,tags:['scheiding','geregistreerd partnerschap','procedure'],bron:'Burgerlijk Wetboek'},
 {id:'dgx-088',thema:'doelgroepen',vraag:'Hebben ongehuwd samenwonenden na scheiding recht op partneralimentatie?',antwoord:`Nee, de wet kent geen partneralimentatie voor samenwoners. Kinderalimentatie is wel mogelijk als er kinderen zijn. Afspraken in een samenlevingscontract kunnen wel gevolgen hebben. Vraag het contract op.`,tags:['scheiding','samenwonen','alimentatie'],bron:'Burgerlijk Wetboek'},
 {id:'dgx-089',thema:'doelgroepen',vraag:'Hoe werkt de eigenwoningreserve voor de partner die vertrekt?',antwoord:`Krijgt de vertrekkende partner een deel van de overwaarde, dan kan voor die partner een eigenwoningreserve ontstaan. Bij aankoop van een nieuwe woning binnen drie jaar beperkt die reserve de aftrekbare schuld. Daarna vervalt de reserve. Bereken de reserve en informeer de klant.`,tags:['scheiding','eigenwoningreserve','bijleenregeling'],bron:'Wet IB 2001'},
 {id:'dgx-090',thema:'doelgroepen',vraag:'Hoe toets je de ex-partner die de woning alleen overneemt?',antwoord:`De overnemende partner wordt getoetst als alleenstaande. Volgens de leennormen 2026 geldt voor alleenstaanden 17.000 euro extra leenruimte. Ontvangen of betaalde alimentatie wordt verwerkt volgens de normen. Controleer de voorwaarden van de geldverstrekker.`,tags:['scheiding','alleenstaanden','toetsing'],bron:'Nibud'},
 {id:'dgx-091',thema:'doelgroepen',vraag:'Wat als een ex-partner al een nieuwe woning wil kopen voor het ontslag uit hoofdelijkheid?',antwoord:`De oude hypotheek telt dan nog als verplichting mee. Daardoor is de leenruimte vaak lager. Vraag of het ontslag al is aangevraagd en wat de status is. Plan de aankoop zo mogelijk na het ontslag.`,tags:['scheiding','hoofdelijkheid','nieuwe woning'],bron:''},
 {id:'dgx-092',thema:'doelgroepen',vraag:'Wanneer moet een scheidingsadvies starten?',antwoord:`Bij voorkeur voordat het convenant definitief is. Dan kunnen de afspraken worden afgestemd op wat financieel haalbaar is. Een convenant met een onhaalbare overname leidt tot problemen. Stem af met de mediator of advocaat.`,tags:['scheiding','planning','convenant'],bron:''},
 {id:'dgx-093',thema:'doelgroepen',vraag:'Welke rol heeft de adviseur naast de mediator bij scheiding?',antwoord:`De mediator begeleidt de afspraken tussen partners. De adviseur toetst of de financiering en verzekeringen haalbaar zijn. Bewaak dat je alleen adviseert binnen je eigen vakgebied. Leg vast voor wie je optreedt en welke rol je hebt.`,tags:['scheiding','mediator','rolverdeling'],bron:''},
 {id:'dgx-094',thema:'doelgroepen',vraag:'Wat is overbedeling bij scheiding?',antwoord:`Overbedeling betekent dat een partner meer krijgt dan het eigen deel. Die partner moet dan het verschil vergoeden. Wordt dat niet direct betaald, dan ontstaat een vordering. Leg vast hoe de overbedeling is berekend en betaald.`,tags:['scheiding','overbedeling','vordering'],bron:'Burgerlijk Wetboek'},
 {id:'dgx-095',thema:'doelgroepen',vraag:'Hoe verwerk je betaalde kinderalimentatie in de toetsing?',antwoord:`Betaalde kinderalimentatie beïnvloedt de betaalbaarheid. Geldverstrekkers verwerken die volgens hun eigen beleid. Vraag het ouderschapsplan of de beschikking op. Controleer de voorwaarden van de geldverstrekker.`,tags:['scheiding','kinderalimentatie','toetsing'],bron:''},
 {id:'dgx-096',thema:'doelgroepen',vraag:'Welke stukken van de geldverstrekker vraag je op bij scheiding?',antwoord:`Vraag het actuele saldo en de rentevaste periode per leningdeel op. Vraag ook de voorwaarden voor overname door een partner. Controleer of er een boete is bij wijziging. Bewaar deze stukken in het dossier.`,tags:['scheiding','documenten','geldverstrekker'],bron:''},
 {id:'dgx-097',thema:'doelgroepen',vraag:'Hoe beïnvloedt co-ouderschap de woonwens na scheiding?',antwoord:`Bij co-ouderschap hebben beide ouders ruimte voor de kinderen nodig. Vaak willen beide in dezelfde buurt blijven wonen. Dat geeft voor twee huishoudens hogere woonlasten. Bespreek de haalbaarheid voor beide huishoudens.`,tags:['scheiding','kinderen','woonbehoefte'],bron:''},
 {id:'dgx-098',thema:'doelgroepen',vraag:'Wat als een ex-partner niet meewerkt aan verkoop of verdeling van de woning?',antwoord:`Dan kan de andere partner de rechter vragen de wijze van verdeling vast te stellen. Dat kost tijd en geld. Intussen blijven beide meestal hoofdelijk aansprakelijk voor de hypotheek. Bespreek de gevolgen voor de planning en leg de status vast.`,tags:['scheiding','verdeling','rechter'],bron:'Burgerlijk Wetboek'},
 {id:'dgx-099',thema:'doelgroepen',vraag:'Kan een partner na de echtscheiding tijdelijk in de woning blijven?',antwoord:`De rechter kan een ex-echtgenoot voor een beperkte periode het gebruik van de woning toekennen. Dit regelt niet wie eigenaar blijft. De lasten en de fiscale behandeling moeten apart worden geregeld. Leg de afspraken over betaling van rente en aflossing vast.`,tags:['scheiding','gebruiksrecht','woning'],bron:'Burgerlijk Wetboek'},
 {id:'dgx-100',thema:'doelgroepen',vraag:'Wat leg je vast als ex-partners de verdeling van de woning uitstellen?',antwoord:`Leg vast wie de lasten betaalt en wie er woont. Noteer tot wanneer de vertrekkende partner fiscaal nog een eigen woning heeft. Beschrijf wat er gebeurt bij waardedaling of betalingsproblemen. Leg een uiterste datum voor verkoop of overname vast.`,tags:['scheiding','uitstel','dossier'],bron:''},
 {id:'dgx-101',thema:'doelgroepen',vraag:'Hoe ga je om met een gezamenlijke onderneming van ex-partners?',antwoord:`De scheiding raakt dan ook de onderneming en het inkomen van beide. Vraag hoe de onderneming wordt verdeeld of voortgezet. Het toekomstige inkomen kan sterk afwijken van de historische cijfers. Overleg met de accountant en leg de uitgangspunten vast.`,tags:['scheiding','ondernemers','inkomen'],bron:''},
 {id:'dgx-102',thema:'doelgroepen',vraag:'Welke veelgemaakte fout zie je bij een scheidingsdossier?',antwoord:`De afspraken in het convenant sluiten niet aan op de financiering. Bijvoorbeeld een overnamebedrag dat hoger is dan de haalbare lening. Ook ontbreekt soms de fiscale splitsing van leningdelen. Toets de afspraken voordat het convenant wordt getekend.`,tags:['scheiding','veelgemaakte fouten','convenant'],bron:''},
 {id:'dgx-103',thema:'doelgroepen',vraag:'Over hoeveel jaren kijkt een geldverstrekker naar het inkomen van een ondernemer?',antwoord:`Veel geldverstrekkers kijken naar de cijfers over de laatste drie jaar. Vaak wordt gerekend met een gemiddelde, maar niet hoger dan het laatste jaar. De exacte methode verschilt per geldverstrekker. Controleer de voorwaarden van de geldverstrekker.`,tags:['ondernemers','inkomen','jaarcijfers'],bron:''},
 {id:'dgx-104',thema:'doelgroepen',vraag:'Hoe beoordeel je een ondernemer met een dalend resultaat?',antwoord:`Een dalende lijn weegt zwaarder dan een gemiddelde. Vraag naar de oorzaak en de verwachting voor de komende jaren. Een inkomensverklaring van een rekenexpert kan dit onderbouwen. Leg de motivering en de risicobespreking vast.`,tags:['ondernemers','dalend resultaat','inkomensverklaring'],bron:''},
 {id:'dgx-105',thema:'doelgroepen',vraag:'Welke stukken vraag je bij een ondernemer met een eenmanszaak?',antwoord:`Vraag de jaarrekeningen en aangiften inkomstenbelasting van de laatste jaren op. Vraag ook de definitieve aanslagen als die er zijn. Vraag een uittreksel uit het Handelsregister. Controleer of er belastingschulden openstaan.`,tags:['ondernemers','documenten','eenmanszaak'],bron:'KVK'},
 {id:'dgx-106',thema:'doelgroepen',vraag:'Hoe wordt de winstverdeling in een vof meegenomen?',antwoord:`Bij een vof telt het winstaandeel van de klant mee, niet de totale winst. De winstverdeling staat in de vennootschapsovereenkomst. Vraag die overeenkomst op. Let ook op de hoofdelijke aansprakelijkheid voor schulden van de vof.`,tags:['ondernemers','vof','winstverdeling'],bron:''},
 {id:'dgx-107',thema:'doelgroepen',vraag:'Wat is het risico van een zzp-er met één opdrachtgever?',antwoord:`De continuïteit hangt dan af van één klant. Valt die weg, dan daalt het inkomen sterk. Ook kan de arbeidsrelatie anders worden beoordeeld dan als zelfstandig ondernemerschap. Bespreek deze risico's en leg ze vast.`,tags:['ondernemers','zzp','opdrachtgever','risico'],bron:''},
 {id:'dgx-108',thema:'doelgroepen',vraag:'Wat is het verschil tussen winst en privé-opnamen bij de toetsing?',antwoord:`Geldverstrekkers toetsen op het inkomen uit de onderneming, niet op wat de ondernemer opneemt. Hoge opnamen kunnen wijzen op druk op de onderneming. Lage opnamen bij hoge winst kunnen wijzen op vermogensopbouw. Bekijk ook de ontwikkeling van het ondernemingsvermogen.`,tags:['ondernemers','winst','privé-opnamen'],bron:''},
 {id:'dgx-109',thema:'doelgroepen',vraag:'Wanneer wordt iemand voor de toetsing als dga gezien?',antwoord:`Dat hangt af van de omvang van het aandelenbelang en de zeggenschap. Geldverstrekkers hanteren hiervoor eigen criteria. Een werknemer met een klein belang kan soms als gewone werknemer worden getoetst. Controleer de voorwaarden van de geldverstrekker.`,tags:['dga','aandelenbelang','toetsing'],bron:''},
 {id:'dgx-110',thema:'doelgroepen',vraag:'Wat is de gebruikelijkloonregeling bij een dga?',antwoord:`Een dga moet in de regel een salaris uit de bv ontvangen dat past bij de werkzaamheden. Het salaris kan bij de toetsing anders worden gewogen dan winst die in de bv blijft. Verwijs voor de actuele normbedragen naar de Belastingdienst. Vraag de loonstroken en de jaarstukken van de bv op.`,tags:['dga','gebruikelijk loon','salaris'],bron:'Wet op de loonbelasting 1964'},
 {id:'dgx-111',thema:'doelgroepen',vraag:'Telt winst die in de bv blijft mee bij een dga?',antwoord:`Sommige geldverstrekkers rekenen ook met de winst die in de bv blijft. Ze kijken dan naar het totale inkomen dat aan de dga toe te rekenen is. Een inkomensverklaring kan dit onderbouwen. Controleer de voorwaarden van de geldverstrekker.`,tags:['dga','winst','inkomensverklaring'],bron:''},
 {id:'dgx-112',thema:'doelgroepen',vraag:'Waarom is de rekening-courant van een dga een aandachtspunt?',antwoord:`Een hoge schuld van de dga aan de bv kan fiscale gevolgen hebben. Sinds 2023 worden schulden boven een drempel bij de eigen bv als fictief inkomen belast. Ook kan een geldverstrekker de schuld meenemen als verplichting. Verwijs voor het actuele drempelbedrag naar de Belastingdienst.`,tags:['dga','rekening-courant','excessief lenen'],bron:'Wet IB 2001'},
 {id:'dgx-113',thema:'doelgroepen',vraag:'Telt een eigenwoningschuld bij de eigen bv mee voor excessief lenen?',antwoord:`Eigenwoningschulden kunnen buiten de regeling vallen. Voor nieuwe eigenwoningschulden moet dan wel een hypotheekrecht zijn gevestigd. Controleer de voorwaarden en de ingangsdatum. Laat de structuur zo nodig fiscaal toetsen.`,tags:['dga','excessief lenen','eigenwoningschuld'],bron:'Wet IB 2001'},
 {id:'dgx-114',thema:'doelgroepen',vraag:'Waar let je op als een dga de hypotheek bij de eigen bv afsluit?',antwoord:`De lening moet zakelijk zijn, met een marktconforme rente en een schriftelijke overeenkomst. Voor renteaftrek geldt de aflossingseis van minimaal annuïtair in 360 maanden. De dga moet de gegevens van de lening in de aangifte vermelden. Leg de afspraken vast.`,tags:['dga','eigen bv','familiehypotheek','aflossingseis'],bron:'Wet IB 2001'},
 {id:'dgx-115',thema:'doelgroepen',vraag:'Wat is er veranderd aan pensioen in eigen beheer bij een dga?',antwoord:`Sinds 2017 kan een dga geen nieuw pensioen in eigen beheer meer opbouwen. Bestaande aanspraken zijn bevroren, afgekocht of omgezet in een oudedagsverplichting. Vraag welke keuze is gemaakt. Neem dit mee bij de toetsing op pensioeninkomen.`,tags:['dga','pensioen in eigen beheer','oudedagsverplichting'],bron:'Wet uitfasering pensioen in eigen beheer'},
 {id:'dgx-116',thema:'doelgroepen',vraag:'Bestaat de fiscale oudedagsreserve nog?',antwoord:`Sinds 2023 kan een ondernemer niet meer toevoegen aan de fiscale oudedagsreserve. Een bestaande reserve blijft bestaan en moet later fiscaal worden afgewikkeld. Vraag naar de omvang van de reserve. Bespreek hoe de ondernemer het pensioen opbouwt.`,tags:['ondernemers','FOR','pensioen'],bron:'Wet IB 2001'},
 {id:'dgx-117',thema:'doelgroepen',vraag:'Hoe bespreek je arbeidsongeschiktheid met een ondernemer zonder AOV?',antwoord:`Zonder verzekering valt het inkomen bij ziekte vaak grotendeels weg. Bereken hoe lang de buffer de woonlasten kan dragen. Bespreek alternatieven zoals een woonlastenverzekering of eigen vermogen. Leg vast dat de klant de risico's kent en welke keuze is gemaakt.`,tags:['ondernemers','arbeidsongeschiktheid','AOV','buffer'],bron:''},
 {id:'dgx-118',thema:'doelgroepen',vraag:'Hoe financier je een woning met bedrijfsruimte?',antwoord:`Alleen het deel dat als hoofdverblijf dient, kan eigen woning zijn. De schuld moet dan worden gesplitst over het woongedeelte en het bedrijfsgedeelte. Vraag een taxatie waarin beide delen zijn gewaardeerd. Controleer de voorwaarden van de geldverstrekker.`,tags:['ondernemers','bedrijfsruimte','gemengd gebruik'],bron:'Wet IB 2001'},
 {id:'dgx-119',thema:'doelgroepen',vraag:'Kan een ondernemer met één boekjaar een hypotheek krijgen?',antwoord:`Dat kan bij sommige geldverstrekkers met een inkomensverklaring. Relevante ervaring in loondienst in dezelfde branche kan helpen. Een prognose kan worden meegewogen, maar is geen garantie. Controleer de voorwaarden van de geldverstrekker.`,tags:['ondernemers','startende ondernemer','inkomensverklaring'],bron:''},
 {id:'dgx-120',thema:'doelgroepen',vraag:'Hoe weeg je een incidenteel verliesjaar bij een ondernemer?',antwoord:`Een eenmalig verlies hoeft niet doorslaggevend te zijn. Vraag naar de oorzaak en het herstel daarna. Een rekenexpert kan beoordelen of het verlies incidenteel is. Leg de onderbouwing vast.`,tags:['ondernemers','verlies','inkomensverklaring'],bron:''},
 {id:'dgx-121',thema:'doelgroepen',vraag:'Waarom vraag je een ondernemer naar zakelijke kredieten?',antwoord:`Zakelijke kredieten staan niet altijd zichtbaar in de BKR-registratie. Toch kunnen ze de draagkracht beïnvloeden, zeker bij persoonlijke aansprakelijkheid. Vraag naar borgstellingen en hoofdelijke aansprakelijkheid. Leg de antwoorden vast.`,tags:['ondernemers','zakelijke kredieten','borgstelling'],bron:''},
 {id:'dgx-122',thema:'doelgroepen',vraag:'Hoe ga je om met belastingschulden van een ondernemer?',antwoord:`Openstaande belastingschulden verlagen de draagkracht. Vraag een overzicht van openstaande aanslagen op. Een betalingsregeling moet worden meegenomen als verplichting. Controleer de voorwaarden van de geldverstrekker.`,tags:['ondernemers','belastingschuld','verplichtingen'],bron:''},
 {id:'dgx-123',thema:'doelgroepen',vraag:'Wat is een meewerkende partner bij een ondernemer?',antwoord:`Een partner die meewerkt in de onderneming kan een meewerkbeloning of arbeidsbeloning krijgen. Dat inkomen hangt af van de onderneming. Bij problemen in de onderneming dalen beide inkomens. Weeg dit concentratierisico mee in het advies.`,tags:['ondernemers','meewerkende partner','risico'],bron:''},
 {id:'dgx-124',thema:'doelgroepen',vraag:'Hoe wordt dividend uit een holding meegenomen bij de toetsing?',antwoord:`Dividend is minder voorspelbaar dan salaris. Geldverstrekkers kijken vaak naar de winstcapaciteit van de bv en niet naar losse dividenden. Vraag de jaarstukken van alle relevante vennootschappen op. Controleer de voorwaarden van de geldverstrekker.`,tags:['dga','dividend','holding'],bron:''},
 {id:'dgx-125',thema:'doelgroepen',vraag:'Hoe verwerk je een stakingswinst bij een ondernemer?',antwoord:`Een stakingswinst is eenmalig. Die telt niet mee als structureel inkomen. Haal deze uit de cijfers bij het bepalen van het toetsinkomen. Vraag naar het inkomen na de staking.`,tags:['ondernemers','stakingswinst','incidenteel'],bron:''},
 {id:'dgx-126',thema:'doelgroepen',vraag:'Waar let je op bij een seizoensondernemer?',antwoord:`Het inkomen is ongelijk verdeeld over het jaar. Kijk naar het jaarinkomen en niet naar losse maanden. Bespreek hoe de woonlasten in de rustige maanden worden betaald. Leg de bufferafspraak vast.`,tags:['ondernemers','seizoen','buffer'],bron:''},
 {id:'dgx-127',thema:'doelgroepen',vraag:'Hoe weeg je inkomsten uit freelancewerk naast loondienst?',antwoord:`Freelance-inkomen naast loondienst telt alleen mee als het voldoende bestendig is. Vaak is een cijferhistorie van meerdere jaren nodig. Vraag de aangiften inkomstenbelasting op. Controleer de voorwaarden van de geldverstrekker.`,tags:['ondernemers','freelance','neveninkomsten'],bron:''},
 {id:'dgx-128',thema:'doelgroepen',vraag:'Welke fout zie je vaak bij het inkomen van ondernemers?',antwoord:`Men gebruikt alleen het beste jaar of een optimistische prognose. Ook worden privé-uitgaven via de zaak niet herkend. Gebruik onafhankelijke cijfers en laat zo nodig een inkomensverklaring maken. Leg de berekening vast.`,tags:['ondernemers','veelgemaakte fouten','inkomen'],bron:''},
 {id:'dgx-129',thema:'doelgroepen',vraag:'Hoe beoordeel je de toekomstbestendigheid van een onderneming?',antwoord:`Kijk naar de sector, de klantspreiding en de afhankelijkheid van enkele opdrachtgevers. Vraag naar investeringsplannen en schulden van de onderneming. Een rekenexpert kan dit onderbouwen. Leg je observaties vast in het dossier.`,tags:['ondernemers','continuïteit','risico'],bron:''},
 {id:'dgx-130',thema:'doelgroepen',vraag:'Hoe bespreek je pensioenopbouw met een zelfstandige?',antwoord:`Een zelfstandige bouwt meestal geen pensioen via een werkgever op. Er is dan alleen AOW en wat de ondernemer zelf regelt. Bereken de woonlasten na de AOW-leeftijd. Bespreek de mogelijkheden voor eigen opbouw.`,tags:['ondernemers','pensioen','AOW'],bron:''},
 {id:'dgx-131',thema:'doelgroepen',vraag:'Welke rol speelt de huwelijksvorm bij een ondernemer?',antwoord:`Bij gemeenschap van goederen kunnen zakelijke schulden ook de partner raken. Huwelijkse voorwaarden kunnen het privévermogen beschermen. Vraag naar de huwelijksvorm en eventuele voorwaarden. Leg dit vast in het dossier.`,tags:['ondernemers','huwelijkse voorwaarden','aansprakelijkheid'],bron:'Burgerlijk Wetboek'},
 {id:'dgx-132',thema:'doelgroepen',vraag:'Hoe beoordeel je een ondernemer die net een bedrijf heeft overgenomen?',antwoord:`De historische cijfers horen bij de vorige eigenaar. Het toekomstige inkomen hangt af van de financiering van de overname. Vraag de overnamedocumenten en de nieuwe financieringslasten op. Controleer de voorwaarden van de geldverstrekker.`,tags:['ondernemers','overname','inkomen'],bron:''},
 {id:'dgx-133',thema:'doelgroepen',vraag:'Wat zijn de uitzendfasen en waarom zijn ze relevant?',antwoord:`In de uitzendbranche lopen werknemers via fasen naar meer zekerheid. In de latere fasen is er meer zekerheid over werk en inkomen. De fase beïnvloedt hoe het inkomen wordt beoordeeld. Vraag de fase op in de werkgeversverklaring.`,tags:['flexwerkers','uitzendfasen','zekerheid'],bron:''},
 {id:'dgx-134',thema:'doelgroepen',vraag:'Hoe beoordeel je een oproepkracht met een nulurencontract?',antwoord:`Bij een nulurencontract is er geen gegarandeerd aantal uren. Het inkomen wordt daarom vaak beoordeeld op basis van historie over meerdere jaren. Een inkomensbepaling kan dit onderbouwen. Controleer de voorwaarden van de geldverstrekker.`,tags:['flexwerkers','nulurencontract','oproepkracht'],bron:''},
 {id:'dgx-135',thema:'doelgroepen',vraag:'Wat is een min-maxcontract en hoe telt het inkomen?',antwoord:`Bij een min-maxcontract staat een minimum aantal uren vast. Het minimum is zeker, de extra uren zijn variabel. Geldverstrekkers kijken vaak naar het gemiddelde inkomen over meerdere jaren. Controleer de voorwaarden van de geldverstrekker.`,tags:['flexwerkers','min-maxcontract','inkomen'],bron:''},
 {id:'dgx-136',thema:'doelgroepen',vraag:'Hoe ga je om met een jaar met lager inkomen door ouderschapsverlof?',antwoord:`Een jaar met verlof kan het gemiddelde inkomen drukken. Vraag naar de reden en de duur van het verlof. Sommige geldverstrekkers kunnen hiermee rekening houden. Leg de toelichting vast en controleer de voorwaarden van de geldverstrekker.`,tags:['flexwerkers','ouderschapsverlof','inkomen'],bron:''},
 {id:'dgx-137',thema:'doelgroepen',vraag:'Telt payrollinkomen als gewoon loondienstinkomen?',antwoord:`Een payrollwerknemer is in dienst van het payrollbedrijf. Het inkomen wordt beoordeeld op basis van het type contract. Een vast contract bij het payrollbedrijf weegt anders dan een tijdelijk contract. Vraag een werkgeversverklaring van het payrollbedrijf op.`,tags:['flexwerkers','payroll','contract'],bron:''},
 {id:'dgx-139',thema:'doelgroepen',vraag:'Telt een WW-uitkering mee als inkomen bij een flexwerker?',antwoord:`Een WW-uitkering is tijdelijk. Daarom wordt die meestal niet als structureel inkomen gezien. Bespreek met de klant of het moment van aanvragen goed is. Leg de afweging vast.`,tags:['flexwerkers','WW','uitkering'],bron:'UWV'},
 {id:'dgx-140',thema:'doelgroepen',vraag:'Wat speelt bij een flexwerker met veel wisselende werkgevers?',antwoord:`Gaten tussen dienstverbanden verlagen het gemiddelde inkomen. Vraag naar de reden van de wisselingen. Een inkomensbepaling op basis van UWV-gegevens geeft vaak een goed beeld. Leg de onderbouwing vast.`,tags:['flexwerkers','werkgevers','inkomensbepaling'],bron:'UWV'},
 {id:'dgx-141',thema:'doelgroepen',vraag:'Hoe beoordeel je een gedetacheerde werknemer?',antwoord:`Een gedetacheerde is in dienst van het detacheringsbureau. Het contract met dat bureau is bepalend, niet de opdracht. Vraag de werkgeversverklaring van het detacheringsbureau op. Controleer de voorwaarden van de geldverstrekker.`,tags:['flexwerkers','detachering','contract'],bron:''},
 {id:'dgx-142',thema:'doelgroepen',vraag:'Wanneer wordt een tijdelijk contract een vast contract?',antwoord:`Volgens de ketenregeling ontstaat een vast contract na meer dan drie tijdelijke contracten of na meer dan drie jaar. Er zijn uitzonderingen in cao-afspraken. Vraag naar de contracthistorie van de klant. Dit helpt bij de inschatting van de zekerheid van het inkomen.`,tags:['flexwerkers','ketenregeling','tijdelijk contract'],bron:'Burgerlijk Wetboek'},
 {id:'dgx-143',thema:'doelgroepen',vraag:'Waar let je op bij pensioenopbouw van een flexwerker?',antwoord:`Flexwerkers bouwen soms minder of later pensioen op. Dat kan tot een lager inkomen na pensionering leiden. Vraag het pensioenoverzicht op. Bespreek de gevolgen voor de woonlasten na de AOW-leeftijd.`,tags:['flexwerkers','pensioen','AOW'],bron:''},
 {id:'dgx-144',thema:'doelgroepen',vraag:'Wat is het risico als een tijdelijk contract niet wordt verlengd na het passeren?',antwoord:`Het inkomen kan dan wegvallen terwijl de woonlasten doorlopen. Bespreek dit scenario en de buffer. Bespreek ook een woonlastenverzekering als die past. Leg de risicobespreking vast in het dossier.`,tags:['flexwerkers','tijdelijk contract','risico'],bron:''},
 {id:'dgx-145',thema:'doelgroepen',vraag:'Hoe beoordeel je een flexwerker die net van branche is gewisseld?',antwoord:`De historie in de oude branche zegt dan minder over het toekomstige inkomen. Vraag naar de nieuwe werkgever en het contract. Sommige geldverstrekkers wachten op meer historie. Controleer de voorwaarden van de geldverstrekker.`,tags:['flexwerkers','branchewissel','inkomen'],bron:''},
 {id:'dgx-146',thema:'doelgroepen',vraag:'Welke fout zie je vaak bij flexibel inkomen?',antwoord:`Men rekent met het inkomen van de laatste maanden en zet dat om naar een jaarbedrag. Daardoor ontstaat een te rooskleurig beeld. Gebruik een betrouwbare inkomensbepaling over meerdere jaren. Leg de gebruikte methode vast.`,tags:['flexwerkers','veelgemaakte fouten','inkomen'],bron:''},
 {id:'dgx-147',thema:'doelgroepen',vraag:'Hoe verwerk je ziekte in het inkomensverleden van een flexwerker?',antwoord:`Een periode van ziekte kan het gemiddelde inkomen drukken. Vraag naar de duur en of de klant volledig hersteld is. Sommige geldverstrekkers houden hier rekening mee. Leg de toelichting vast en controleer de voorwaarden van de geldverstrekker.`,tags:['flexwerkers','ziekte','inkomen'],bron:''},
 {id:'dgx-148',thema:'doelgroepen',vraag:'Hoe beoordeel je seizoenswerk in loondienst?',antwoord:`Seizoenswerk geeft inkomen in een deel van het jaar. Kijk naar het jaarinkomen over meerdere jaren. Vraag naar de werkhistorie bij dezelfde werkgever. Controleer de voorwaarden van de geldverstrekker.`,tags:['flexwerkers','seizoenswerk','jaarinkomen'],bron:''},
 {id:'dgx-149',thema:'doelgroepen',vraag:'Wat leg je vast bij een flexwerker met een perspectiefverklaring?',antwoord:`Leg vast welke partij de verklaring afgeeft en welke uren of inkomsten worden genoemd. Noteer ook de looptijd van de verklaring. Leg vast hoe de verklaring is meegenomen in de toetsing. Bewaar de verklaring in het dossier.`,tags:['flexwerkers','perspectiefverklaring','dossier'],bron:''},
 {id:'dgx-150',thema:'doelgroepen',vraag:'Kan een flexwerker met een lage historie toch een hypotheek krijgen?',antwoord:`Dat hangt af van de geldverstrekker en de beschikbare onderbouwing. Een intentieverklaring of perspectiefverklaring kan helpen. Ook een partner met vast inkomen kan de aanvraag dragen. Controleer de voorwaarden van de geldverstrekker.`,tags:['flexwerkers','historie','acceptatie'],bron:''},
 {id:'dgx-151',thema:'doelgroepen',vraag:'Waar let je op bij een grensarbeider die in Nederland woont en in het buitenland werkt?',antwoord:`Het inkomen wordt vaak in het werkland belast. De netto-brutoverhouding kan daardoor afwijken van een Nederlandse loonstrook. Vraag een werkgeversverklaring en de buitenlandse loonstroken op. Controleer de voorwaarden van de geldverstrekker over buitenlands inkomen.`,tags:['buitenlands inkomen','grensarbeider','belasting'],bron:''},
 {id:'dgx-152',thema:'doelgroepen',vraag:'Wat is een kwalificerende buitenlandse belastingplichtige?',antwoord:`Dat is een niet-inwoner van wie het inkomen in hoofdzaak in Nederland wordt belast. Zo iemand kan onder voorwaarden aftrekposten krijgen, zoals hypotheekrente voor een eigen woning in het woonland. De precieze voorwaarden staan in de wet. Verwijs voor de details naar de Belastingdienst.`,tags:['buitenlands inkomen','niet-inwoner','renteaftrek'],bron:'Wet IB 2001'},
 {id:'dgx-153',thema:'doelgroepen',vraag:'Wat is het risico van inkomen in een vreemde valuta?',antwoord:`Bij koersdaling daalt het inkomen omgerekend in euro. De woonlasten in euro blijven gelijk. Bespreek dit valutarisico expliciet met de klant. Leg de risicobespreking vast en controleer de voorwaarden van de geldverstrekker.`,tags:['buitenlands inkomen','valuta','risico'],bron:''},
 {id:'dgx-154',thema:'doelgroepen',vraag:'Hoe beoordeel je een expat met een tijdelijke belastingregeling?',antwoord:`Een tijdelijk belastingvoordeel geeft een hoger netto inkomen zolang het loopt. Na afloop dalen de netto inkomsten. Neem dat mee in de beoordeling van de betaalbaarheid. Verwijs voor de actuele regeling naar de Belastingdienst.`,tags:['buitenlands inkomen','expat','netto inkomen'],bron:'Belastingdienst'},
 {id:'dgx-155',thema:'doelgroepen',vraag:'Wat speelt bij een expat die maar enkele jaren in Nederland blijft?',antwoord:`Bij een korte verblijfsduur zijn de kosten van koop en verkoop relatief hoog. Ook kan de woning moeilijk te verhuren zijn als de klant vertrekt. Bespreek het scenario van vertrek en verhuur. Leg de afweging tussen kopen en huren vast.`,tags:['buitenlands inkomen','expat','verblijfsduur'],bron:''},
 {id:'dgx-156',thema:'doelgroepen',vraag:'Hoe ga je om met een tijdelijke verblijfsvergunning?',antwoord:`Een tijdelijke vergunning geeft onzekerheid over de verblijfsduur. Veel geldverstrekkers stellen eisen aan de soort en de looptijd van de vergunning. Vraag de verblijfsvergunning op en noteer de einddatum. Controleer de voorwaarden van de geldverstrekker.`,tags:['buitenlands inkomen','verblijfsvergunning','acceptatie'],bron:'IND'},
 {id:'dgx-157',thema:'doelgroepen',vraag:'Heeft een EU-burger een verblijfsvergunning nodig voor een hypotheek?',antwoord:`EU-burgers hebben in principe geen verblijfsvergunning nodig. Wel zijn een BSN en een inschrijving in de gemeente nodig. Geldverstrekkers kunnen eigen eisen stellen. Controleer de voorwaarden van de geldverstrekker.`,tags:['buitenlands inkomen','EU-burger','BSN'],bron:''},
 {id:'dgx-158',thema:'doelgroepen',vraag:'Hoe breng je buitenlandse schulden in beeld?',antwoord:`Buitenlandse leningen staan meestal niet in het BKR. Vraag de klant actief naar leningen en verplichtingen in het buitenland. Vraag zo nodig om een buitenlands kredietoverzicht. Laat de klant bevestigen dat het overzicht volledig is.`,tags:['buitenlands inkomen','schulden','BKR'],bron:''},
 {id:'dgx-159',thema:'doelgroepen',vraag:'Hoe telt een werkgeversverklaring van een buitenlandse werkgever?',antwoord:`Niet elke geldverstrekker accepteert een buitenlandse werkgeversverklaring. Soms is een vertaling of een eigen model van de geldverstrekker nodig. Vraag ook de loonstroken en bankafschriften op. Controleer de voorwaarden van de geldverstrekker.`,tags:['buitenlands inkomen','werkgeversverklaring','documenten'],bron:''},
 {id:'dgx-160',thema:'doelgroepen',vraag:'Wanneer is een beëdigde vertaling van documenten nodig?',antwoord:`Documenten in een vreemde taal moeten voor de geldverstrekker en notaris begrijpelijk zijn. Vaak is een beëdigde vertaling vereist. Soms geldt ook een eis van legalisatie of een apostille. Vraag dit tijdig na om vertraging te voorkomen.`,tags:['buitenlands inkomen','vertaling','documenten'],bron:''},
 {id:'dgx-161',thema:'doelgroepen',vraag:'Telt huurinkomen uit een woning in het buitenland mee?',antwoord:`Huurinkomen uit buitenlands vastgoed telt vaak niet of beperkt mee. Het inkomen is lastig te controleren en kan wisselen. Vraag naar de lasten en schulden op die woning. Controleer de voorwaarden van de geldverstrekker.`,tags:['buitenlands inkomen','vastgoed','huur'],bron:''},
 {id:'dgx-162',thema:'doelgroepen',vraag:'Waar let je op bij eigen middelen uit het buitenland?',antwoord:`De herkomst van het geld moet aantoonbaar zijn. Geldverstrekker en notaris moeten de herkomst van gelden onderzoeken. Vraag afschriften waaruit de opbouw van het vermogen blijkt. Leg de documentatie vast in het dossier.`,tags:['buitenlands inkomen','eigen middelen','herkomst'],bron:'Wwft'},
 {id:'dgx-163',thema:'doelgroepen',vraag:'Hoe beoordeel je een Nederlander die terugkeert uit het buitenland?',antwoord:`De klant heeft vaak nog geen Nederlandse inkomenshistorie. Het nieuwe contract in Nederland is dan bepalend. Let op een eventueel AOW-gat door jaren buiten Nederland. Controleer de voorwaarden van de geldverstrekker.`,tags:['buitenlands inkomen','remigratie','AOW-gat'],bron:'SVB'},
 {id:'dgx-164',thema:'doelgroepen',vraag:'Kan iemand die nog in het buitenland woont een woning in Nederland kopen als toekomstig hoofdverblijf?',antwoord:`Dat kan, maar de acceptatie verschilt per geldverstrekker. De woning moet daadwerkelijk het hoofdverblijf worden voor renteaftrek. Vraag naar de verhuisdatum en het toekomstige inkomen in Nederland. Leg de planning vast.`,tags:['buitenlands inkomen','hoofdverblijf','acceptatie'],bron:''},
 {id:'dgx-165',thema:'doelgroepen',vraag:'Valt een tweede woning in het buitenland onder de eigen woning?',antwoord:`Nee, een tweede woning is geen eigen woning. Een woning in het buitenland die geen hoofdverblijf is, valt bij een inwoner van Nederland in box 3. De rente op een lening daarvoor is niet aftrekbaar als eigenwoningrente. Bespreek ook de belastingregels in het andere land.`,tags:['buitenlands inkomen','tweede woning','box 3'],bron:'Wet IB 2001'},
 {id:'dgx-166',thema:'doelgroepen',vraag:'Welk huwelijksvermogensrecht geldt bij partners met een buitenlandse achtergrond?',antwoord:`Bij een internationale situatie kan buitenlands recht van toepassing zijn op het huwelijksvermogen. Dat bepaalt mede wie eigenaar is van de woning en wie aansprakelijk is. Vraag naar de plaats van het huwelijk en eventuele afspraken. Verwijs zo nodig naar een notaris.`,tags:['buitenlands inkomen','huwelijksvermogensrecht','notaris'],bron:''},
 {id:'dgx-167',thema:'doelgroepen',vraag:'Welk erfrecht geldt bij een klant met een buitenlandse nationaliteit?',antwoord:`Binnen de EU geldt in principe het recht van het land van gewone verblijfplaats. De klant kan in een testament kiezen voor het recht van de nationaliteit. Dit beïnvloedt wie de woning erft. Verwijs voor maatwerk naar een notaris.`,tags:['buitenlands inkomen','erfrecht','rechtskeuze'],bron:'Europese Erfrechtverordening'},
 {id:'dgx-168',thema:'doelgroepen',vraag:'Wat speelt bij inkomen van een internationale organisatie?',antwoord:`Medewerkers van sommige internationale organisaties betalen geen Nederlandse belasting over hun salaris. Het netto inkomen wijkt dan af van een gewoon loon. Geldverstrekkers hebben hiervoor eigen rekenregels. Controleer de voorwaarden van de geldverstrekker.`,tags:['buitenlands inkomen','internationale organisatie','netto inkomen'],bron:''},
 {id:'dgx-169',thema:'doelgroepen',vraag:'Waar let je op bij werk op afstand voor een buitenlandse werkgever?',antwoord:`Bij thuiswerken in Nederland voor een buitenlandse werkgever kan de belastingheffing ingewikkeld zijn. Ook is het contract soms naar buitenlands recht. Vraag het contract en de loonstroken op. Controleer de voorwaarden van de geldverstrekker.`,tags:['buitenlands inkomen','thuiswerk','buitenlandse werkgever'],bron:''},
 {id:'dgx-170',thema:'doelgroepen',vraag:'Wat is het verschil tussen een lokaal contract en een uitzending vanuit het buitenland?',antwoord:`Bij een lokaal contract is de klant in dienst bij een Nederlandse vestiging. Bij een uitzending blijft de klant in dienst in het buitenland en is het verblijf tijdelijk. Een lokaal contract geeft meestal meer zekerheid. Leg het type contract vast.`,tags:['buitenlands inkomen','uitzending','contract'],bron:''},
 {id:'dgx-171',thema:'doelgroepen',vraag:'Hoe ga je om met een partner die nog geen inkomen in Nederland heeft?',antwoord:`Toekomstig inkomen telt meestal niet mee zolang het niet aantoonbaar is. De toetsing gebeurt dan op het inkomen van de andere partner. Bespreek of de partner later meer inkomen krijgt. Leg vast dat dit niet in de toetsing is meegenomen.`,tags:['buitenlands inkomen','partner','toetsing'],bron:''},
 {id:'dgx-172',thema:'doelgroepen',vraag:'Wat doe je bij een klant die het Nederlands niet goed beheerst?',antwoord:`Het advies moet begrijpelijk zijn voor de klant. Overweeg een tolk of informatie in een taal die de klant begrijpt. Controleer of de klant de belangrijkste risico's echt begrijpt. Leg vast hoe de communicatie is verlopen.`,tags:['buitenlands inkomen','taal','begrijpelijkheid'],bron:'Wft'},
 {id:'dgx-173',thema:'doelgroepen',vraag:'Wat speelt bij buitenlands pensioen dat in de toekomst wordt uitgekeerd?',antwoord:`Een buitenlands pensioen kan in een andere valuta en onder andere regels worden uitgekeerd. Vraag een overzicht van de uitvoerder op. Let op belastingheffing en koersrisico. Neem het pensioen voorzichtig mee in de berekening na de AOW-leeftijd.`,tags:['buitenlands inkomen','pensioen','valuta'],bron:''},
 {id:'dgx-174',thema:'doelgroepen',vraag:'Welke veelgemaakte fout zie je bij buitenlands inkomen?',antwoord:`Men neemt het bruto bedrag over zonder te letten op belasting en valuta. Ook wordt de zekerheid van het contract vaak niet goed beoordeeld. Vraag volledige stukken op en vergelijk die met bankafschriften. Leg de beoordeling vast.`,tags:['buitenlands inkomen','veelgemaakte fouten','beoordeling'],bron:''},
 {id:'dgx-175',thema:'doelgroepen',vraag:'Wanneer kan dubbele belasting een rol spelen bij buitenlands inkomen?',antwoord:`Als een klant inkomen heeft uit meer landen, kunnen beide landen belasting willen heffen. Belastingverdragen regelen welk land mag heffen. Dit beïnvloedt het netto inkomen. Verwijs voor de fiscale afwikkeling naar een fiscalist.`,tags:['buitenlands inkomen','belastingverdrag','dubbele belasting'],bron:''},
 {id:'dgx-176',thema:'doelgroepen',vraag:'Wanneer zijn ongehuwd samenwonenden fiscale partners?',antwoord:`Samenwoners die op hetzelfde adres staan ingeschreven, zijn fiscale partners als zij aan een van de wettelijke voorwaarden voldoen. Voorbeelden zijn een notarieel samenlevingscontract, een gezamenlijk kind of samen eigenaar zijn van de woning waar zij wonen. Ook aanmelding als partner bij een pensioenfonds telt. Controleer de actuele voorwaarden bij de Belastingdienst.`,tags:['samenwonen','fiscaal partnerschap','voorwaarden'],bron:'Wet IB 2001'},
 {id:'dgx-178',thema:'doelgroepen',vraag:'Wat als partners ongelijk eigen geld inbrengen bij aankoop?',antwoord:`De partner die meer inbrengt, loopt risico bij uit elkaar gaan of overlijden. Dit kan worden geregeld via de eigendomsverhouding, een lening tussen partners of een verrekenafspraak. Adviseer om dit notarieel vast te leggen. Leg in het dossier vast dat het onderwerp is besproken.`,tags:['samenwonen','eigen inbreng','samenlevingscontract'],bron:''},
 {id:'dgx-179',thema:'doelgroepen',vraag:'Waarom is een onderhands samenlevingscontract soms onvoldoende?',antwoord:`Voor fiscaal partnerschap is een notarieel samenlevingscontract nodig als er geen andere voorwaarde geldt. Ook pensioenfondsen vragen vaak een notarieel contract voor partnerpensioen. Een onderhands contract biedt minder bewijs. Adviseer om de vorm te laten beoordelen door een notaris.`,tags:['samenwonen','samenlevingscontract','notaris'],bron:''},
 {id:'dgx-180',thema:'doelgroepen',vraag:'Moet een samenwonende partner worden aangemeld bij het pensioenfonds?',antwoord:`Bij veel pensioenfondsen moet de ongehuwde partner worden aangemeld voor partnerpensioen. Zonder aanmelding kan het recht vervallen. Vraag de klant de aanmelding te controleren. Leg dit vast als actiepunt.`,tags:['samenwonen','partnerpensioen','aanmelding'],bron:''},
 {id:'dgx-181',thema:'doelgroepen',vraag:'Welke rechten heeft een partner die niet mede-eigenaar is van de woning?',antwoord:`Zonder eigendom heeft de partner geen recht op de woning. Bij overlijden van de eigenaar kan de partner zonder testament of afspraken de woning moeten verlaten. Bespreek mede-eigendom of afspraken in een testament. Verwijs naar een notaris voor maatwerk.`,tags:['samenwonen','eigendom','overlijden'],bron:'Burgerlijk Wetboek'},
 {id:'dgx-182',thema:'doelgroepen',vraag:'Wanneer krijgt een samenwonende partner de partnervrijstelling in de erfbelasting?',antwoord:`Dat kan onder voorwaarden, onder meer bij een notarieel samenlevingscontract met een wederzijdse zorgverplichting en een minimale periode van samenwonen. Zonder contract is een langere periode van samenwonen vereist. Controleer de actuele voorwaarden en het actuele bedrag bij de Belastingdienst. Leg vast welke situatie geldt.`,tags:['samenwonen','erfbelasting','partnervrijstelling'],bron:'Successiewet 1956'},
 {id:'dgx-183',thema:'doelgroepen',vraag:'Waarom kiezen samenwoners vaak voor een kruislings ORV?',antwoord:`Bij een kruislingse polis is de begunstigde ook verzekeringnemer en betaalt die de premie. Dan valt de uitkering in de regel niet onder de erfbelasting. Dat kan gunstig zijn als er geen of een beperkte partnervrijstelling is. Controleer of de premiebetaling ook echt kruislings verloopt.`,tags:['samenwonen','ORV','kruislings','erfbelasting'],bron:'Successiewet 1956'},
 {id:'dgx-184',thema:'doelgroepen',vraag:'Hoe telt het inkomen van beide samenwoners mee in de toetsing?',antwoord:`Volgens de leennormen 2026 telt het tweede inkomen volledig mee. Beide inkomens tellen dus volledig op in het toetsinkomen. Bespreek ook het scenario waarin een van beiden minder gaat werken.`,tags:['samenwonen','tweede inkomen','leennormen'],bron:'Nibud'},
 {id:'dgx-185',thema:'doelgroepen',vraag:'Wat als een partner schulden heeft bij samen kopen?',antwoord:`Bij een gezamenlijke aanvraag tellen de schulden van beide partners mee. Beide worden meestal hoofdelijk aansprakelijk voor de hypotheek. Bespreek de gevolgen bij uit elkaar gaan. Leg de bespreking van dit risico vast.`,tags:['samenwonen','schulden','hoofdelijkheid'],bron:''},
 {id:'dgx-186',thema:'doelgroepen',vraag:'Wat als een partner intrekt in de woning van de ander?',antwoord:`De woning en hypotheek blijven op naam van de eigenaar. Betaalt de nieuwe partner mee, dan is het verstandig afspraken vast te leggen. Bespreek wat er gebeurt bij uit elkaar gaan of overlijden. Verwijs voor de juridische afspraken naar een notaris.`,tags:['samenwonen','intrekken','afspraken'],bron:''},
 {id:'dgx-187',thema:'doelgroepen',vraag:'Is overdrachtsbelasting verschuldigd als een samenwoner de helft van de woning overneemt?',antwoord:`Bij overdracht van een aandeel in de woning tussen ongehuwde partners kan overdrachtsbelasting verschuldigd zijn. Welk tarief of welke vrijstelling geldt, hangt af van de situatie. Laat dit vooraf toetsen door de notaris. Neem de kosten mee in de berekening.`,tags:['samenwonen','overdrachtsbelasting','eigendomsoverdracht'],bron:'Wet op belastingen van rechtsverkeer'},
 {id:'dgx-188',thema:'doelgroepen',vraag:'Wat verandert er voor de woning als samenwoners gaan trouwen?',antwoord:`Bij trouwen gaat het huwelijksvermogensrecht gelden. Dat kan invloed hebben op wie eigenaar is van de woning en schulden. Bespreek of huwelijkse voorwaarden wenselijk zijn. Verwijs naar een notaris voor maatwerk.`,tags:['samenwonen','huwelijk','eigendom'],bron:'Burgerlijk Wetboek'},
 {id:'dgx-189',thema:'doelgroepen',vraag:'Hoe kan een schenking van ouders aan één partner worden beschermd?',antwoord:`Bij samenwoners kan het geld via een afspraak in het samenlevingscontract aan de ontvangende partner worden toegerekend. Bij gehuwden kan een uitsluitingsclausule bij de schenking helpen. Leg vast hoe de schenking in de woning is gestoken. Verwijs voor de vorm naar een notaris.`,tags:['samenwonen','schenking','uitsluitingsclausule'],bron:''},
 {id:'dgx-190',thema:'doelgroepen',vraag:'Wat als beide samenwoners al een eigen woning hebben?',antwoord:`Bij samenwonen in een van de woningen kan de andere woning nog maximaal drie jaar eigen woning blijven als die leeg en te koop staat. Wordt die woning verhuurd, dan valt die in box 3. Bespreek de dubbele lasten en de verkoopplanning. Leg de keuze vast.`,tags:['samenwonen','twee woningen','leegstand'],bron:'Wet IB 2001'},
 {id:'dgx-191',thema:'doelgroepen',vraag:'Hoe bepaal je de aftrek bij samenwoners die geen fiscale partners zijn?',antwoord:`Elke partner kan alleen rente aftrekken over de eigen schuld voor het eigen deel van de woning. De verdeling hangt af van eigendom en schuld. Een scheve verhouding kan leiden tot verlies van aftrek. Leg de eigendoms- en schuldverhouding vast.`,tags:['samenwonen','renteaftrek','eigendomsverhouding'],bron:'Wet IB 2001'},
 {id:'dgx-192',thema:'doelgroepen',vraag:'Wat is een verrekenbeding in een samenlevingscontract?',antwoord:`Met een verrekenbeding spreken partners af hoe zij vermogen verrekenen bij uit elkaar gaan. Dat kan bijvoorbeeld de eigen inbreng in de woning betreffen. Zonder afspraak is de eigendom vaak leidend. Laat de afspraak notarieel vastleggen.`,tags:['samenwonen','verrekenbeding','inbreng'],bron:''},
 {id:'dgx-193',thema:'doelgroepen',vraag:'Hoe vaak moet een samenlevingscontract worden herzien?',antwoord:`Bij belangrijke wijzigingen kan het contract verouderd raken. Denk aan aankoop van een woning, kinderen of een flinke wijziging in inkomen. Adviseer de klant het contract dan te laten controleren. Leg dit vast als actiepunt.`,tags:['samenwonen','samenlevingscontract','herziening'],bron:''},
 {id:'dgx-194',thema:'doelgroepen',vraag:'Wat zijn de gevolgen van uit elkaar gaan voor samenwoners met een gezamenlijke woning?',antwoord:`Zij moeten de woning verdelen, verkopen of een partner neemt over. Zonder afspraken kan dit tot conflicten leiden. Ontslag uit de hoofdelijke aansprakelijkheid is nodig voor de vertrekkende partner. Vraag het samenlevingscontract op.`,tags:['samenwonen','uit elkaar','verdeling'],bron:''},
 {id:'dgx-195',thema:'doelgroepen',vraag:'Waar let je op bij een samengesteld gezin dat samen een woning koopt?',antwoord:`Elke partner wil vaak de eigen kinderen beschermen. Zonder testament kan de woning anders terechtkomen dan gewenst. Bespreek eigendom, testament en verzekeringen in samenhang. Verwijs naar een notaris voor maatwerk.`,tags:['samenwonen','samengesteld gezin','testament'],bron:''},
 {id:'dgx-196',thema:'doelgroepen',vraag:'Welke fout zie je vaak bij samenwoners?',antwoord:`Men koopt samen een woning zonder samenlevingscontract of testament. Bij overlijden of uit elkaar gaan blijkt dan dat er niets is geregeld. Bespreek deze punten altijd in het adviesgesprek. Leg vast welke actie de klant onderneemt.`,tags:['samenwonen','veelgemaakte fouten','testament'],bron:''},
 {id:'dgx-197',thema:'doelgroepen',vraag:'Wat leg je vast over de eigendomsverhouding bij samenwoners?',antwoord:`Leg de eigendomsverhouding vast zoals die in de akte komt. Noteer de inbreng van elke partner en eventuele afspraken. Controleer of de hypotheekschuld aansluit op de eigendom. Bewaar dit overzicht in het dossier.`,tags:['samenwonen','eigendomsverhouding','dossier'],bron:''},
 {id:'dgx-198',thema:'doelgroepen',vraag:'Wat betekent alleenstaande toetsing als een partner nog niet samenwoont?',antwoord:`Koopt iemand alleen, dan wordt die als alleenstaande getoetst. Volgens de leennormen 2026 geldt dan 17.000 euro extra leenruimte. Het inkomen van een toekomstige partner telt niet mee. Leg vast hoe de toetsing is gedaan.`,tags:['samenwonen','alleenstaanden','toetsing'],bron:'Nibud'},
 {id:'dgx-199',thema:'doelgroepen',vraag:'Hoe wordt de hypotheekrente verdeeld als partners in de loop van het jaar gaan samenwonen?',antwoord:`Fiscaal partnerschap kan in de loop van het jaar ontstaan. Onder voorwaarden kunnen partners kiezen om het hele jaar als fiscale partners te gelden. Dat beïnvloedt de verdeling van de eigenwoningrente. Verwijs voor de details naar de Belastingdienst.`,tags:['samenwonen','fiscaal partnerschap','aangifte'],bron:'Wet IB 2001'},
 {id:'dgx-200',thema:'doelgroepen',vraag:'Waar let je op bij een buitenlandse partner die in Nederland komt samenwonen?',antwoord:`Controleer de verblijfsstatus en of de partner al inkomen in Nederland heeft. Vraag naar schulden en verplichtingen in het land van herkomst. Bespreek het toepasselijke recht op het vermogen als zij trouwen. Verwijs zo nodig naar een notaris.`,tags:['samenwonen','buitenlands inkomen','verblijfsstatus'],bron:''},
 {id:'dgx-201',thema:'doelgroepen',vraag:'Wat gebeurt er met de woning en de hypotheek bij de wettelijke verdeling?',antwoord:`Bij de wettelijke verdeling krijgt de langstlevende echtgenoot de goederen en ook de schulden. De kinderen krijgen een geldvordering op de langstlevende. De woning en de hypotheek komen dus bij de langstlevende. Controleer of er een testament is dat iets anders regelt.`,tags:['erfrecht','wettelijke verdeling','langstlevende'],bron:'Burgerlijk Wetboek'},
 {id:'dgx-202',thema:'doelgroepen',vraag:'Wanneer is de vordering van kinderen onder de wettelijke verdeling opeisbaar?',antwoord:`De vordering is in principe pas opeisbaar bij overlijden van de langstlevende. Ook bij faillissement of schuldsanering van de langstlevende kan die opeisbaar worden. Een testament kan andere momenten regelen. Dit geeft de langstlevende ruimte om in de woning te blijven.`,tags:['erfrecht','kindsdeel','opeisbaarheid'],bron:'Burgerlijk Wetboek'},
 {id:'dgx-203',thema:'doelgroepen',vraag:'Behoudt de langstlevende het overgangsrecht op de hypotheek van de overleden partner?',antwoord:`Bij verkrijging door vererving kan het overgangsrecht onder voorwaarden behouden blijven. De precieze voorwaarden zijn fiscaal technisch. Controleer de situatie aan de hand van de wet of laat dit fiscaal toetsen. Leg per leningdeel het fiscale regime vast.`,tags:['erfrecht','overgangsrecht','langstlevende'],bron:'Wet IB 2001'},
 {id:'dgx-204',thema:'doelgroepen',vraag:'Wat zijn wilsrechten van kinderen?',antwoord:`Wilsrechten geven kinderen in bepaalde situaties het recht om goederen over te nemen ter voldoening van hun vordering. Dat kan bijvoorbeeld spelen als de langstlevende hertrouwt. Dit kan gevolgen hebben voor de woning. Verwijs voor maatwerk naar een notaris.`,tags:['erfrecht','wilsrechten','hertrouwen'],bron:'Burgerlijk Wetboek'},
 {id:'dgx-205',thema:'doelgroepen',vraag:'Wat gebeurt er fiscaal als kinderen de woning van hun ouder erven?',antwoord:`Gaan de kinderen er niet wonen, dan is de woning voor hen geen eigen woning. De woning valt dan in box 3. De hypotheekrente is voor hen niet aftrekbaar als eigenwoningrente. Bespreek de lasten tot verkoop.`,tags:['erfrecht','kinderen','box 3'],bron:'Wet IB 2001'},
 {id:'dgx-206',thema:'doelgroepen',vraag:'Wanneer is beneficiair aanvaarden verstandig?',antwoord:`Bij twijfel over schulden in de nalatenschap is beneficiair aanvaarden vaak verstandig. Erfgenamen zijn dan in principe niet met hun eigen vermogen aansprakelijk voor schulden van de nalatenschap. Denk aan een woning met mogelijke restschuld. Verwijs voor de procedure naar een notaris.`,tags:['erfrecht','beneficiair aanvaarden','restschuld'],bron:'Burgerlijk Wetboek'},
 {id:'dgx-207',thema:'doelgroepen',vraag:'Wat gebeurt met de hypotheek als een ongehuwde partner overlijdt zonder testament?',antwoord:`Het aandeel van de overledene gaat naar de wettelijke erfgenamen, zoals kinderen, ouders of broers en zussen. De langstlevende partner moet dan mogelijk met hen delen of hen uitkopen. Daarvoor is soms een nieuwe financiering nodig. Bespreek dit risico vooraf en verwijs naar een notaris.`,tags:['erfrecht','samenwonen','testament'],bron:'Burgerlijk Wetboek'},
 {id:'dgx-208',thema:'doelgroepen',vraag:'Hoe stem je de hoogte van een ORV af op de erfrechtelijke situatie?',antwoord:`Kijk wie de woning erft en wie de lasten draagt na overlijden. Bij samenwoners zonder testament kan meer nodig zijn om erfgenamen uit te kopen. Bereken de benodigde dekking per scenario. Leg de berekening vast.`,tags:['erfrecht','ORV','dekking'],bron:''},
 {id:'dgx-209',thema:'doelgroepen',vraag:'Wanneer telt een erfenis als eigen middelen?',antwoord:`Een erfenis telt pas mee als die beschikbaar is. De afwikkeling van een nalatenschap kan maanden duren. Vraag een verklaring van erfrecht en een overzicht van de verdeling op. Plan de aankoop niet op een erfenis die nog niet is afgewikkeld.`,tags:['erfrecht','eigen middelen','nalatenschap'],bron:''},
 {id:'dgx-210',thema:'doelgroepen',vraag:'Waarom check je een testament na een scheiding?',antwoord:`Een oud testament kan een ex-partner nog als erfgenaam noemen. Dat kan ongewenste gevolgen hebben voor de woning. Adviseer de klant het testament te laten controleren. Doe hetzelfde met begunstigingen in verzekeringen.`,tags:['erfrecht','testament','scheiding'],bron:''},
 {id:'dgx-211',thema:'doelgroepen',vraag:'Wat is het belang van een levenstestament bij woningbezit?',antwoord:`Als een klant wilsonbekwaam wordt, kan die niet meer zelf tekenen. Met een levenstestament kan een gevolmachtigde handelen, bijvoorbeeld bij verkoop of oversluiten. Zonder levenstestament is vaak een bewindvoerder via de rechter nodig. Bespreek dit vooral bij senioren.`,tags:['erfrecht','levenstestament','volmacht'],bron:''},
 {id:'dgx-212',thema:'doelgroepen',vraag:'Wat is het verschil tussen een begunstiging op naam en de nalatenschap bij een ORV?',antwoord:`Bij een begunstiging op naam gaat de uitkering direct naar die persoon. Valt de uitkering in de nalatenschap, dan wordt die verdeeld volgens het erfrecht. Dat kan andere personen bevoordelen dan bedoeld. Controleer de begunstiging bij elk advies.`,tags:['erfrecht','ORV','begunstiging'],bron:''},
 {id:'dgx-213',thema:'doelgroepen',vraag:'Wat moet een langstlevende regelen bij de geldverstrekker na overlijden?',antwoord:`Meld het overlijden bij de geldverstrekker en de verzekeraars. Vraag naar de gevolgen voor de lening en eventuele verzekeringen. Een ORV-uitkering kan worden gebruikt om af te lossen. Leg de gemaakte keuzes vast.`,tags:['erfrecht','langstlevende','geldverstrekker'],bron:''},
 {id:'dgx-214',thema:'doelgroepen',vraag:'Wat is een ouderlijke boedelverdeling?',antwoord:`Een ouderlijke boedelverdeling is een vorm van testament waarbij de langstlevende de goederen krijgt. De kinderen krijgen een vordering, net als bij de wettelijke verdeling. Het testament kan de voorwaarden verder regelen. Verwijs voor maatwerk naar een notaris.`,tags:['erfrecht','ouderlijke boedelverdeling','testament'],bron:''},
 {id:'dgx-215',thema:'doelgroepen',vraag:'Wat is een executeur en welke rol speelt die bij de woning?',antwoord:`Een executeur beheert de nalatenschap en betaalt de schulden. De executeur kan de woning beheren en soms verkopen, afhankelijk van de bevoegdheden. Vraag naar het testament en de bevoegdheden. Stem af met de executeur over de hypotheek.`,tags:['erfrecht','executeur','nalatenschap'],bron:'Burgerlijk Wetboek'},
 {id:'dgx-216',thema:'doelgroepen',vraag:'Wat speelt bij erfgenamen die de geërfde woning willen verkopen?',antwoord:`Tot de verkoop dragen de erfgenamen de lasten van de woning. De rente is niet aftrekbaar als eigenwoningrente als zij er niet wonen. Vraag hoe de lasten worden verdeeld. Leg de afspraken tussen erfgenamen vast.`,tags:['erfrecht','verkoop','lasten'],bron:'Wet IB 2001'},
 {id:'dgx-217',thema:'doelgroepen',vraag:'Wat valt bij gehuwden in gemeenschap in de nalatenschap?',antwoord:`Bij een gemeenschap van goederen valt de helft van het gemeenschappelijk vermogen in de nalatenschap. Dat geldt ook voor de woning en de schuld. De andere helft is al van de langstlevende. Gebruik dit bij de berekening van het kindsdeel.`,tags:['erfrecht','gemeenschap van goederen','nalatenschap'],bron:'Burgerlijk Wetboek'},
 {id:'dgx-218',thema:'doelgroepen',vraag:'Wat is een legaat van de woning?',antwoord:`Met een legaat bepaalt de erflater dat een specifieke persoon de woning krijgt. De legataris krijgt een vordering op de erfgenamen tot afgifte. Dit kan gevolgen hebben voor de hypotheek. Verwijs voor maatwerk naar een notaris.`,tags:['erfrecht','legaat','woning'],bron:'Burgerlijk Wetboek'},
 {id:'dgx-219',thema:'doelgroepen',vraag:'Welke veelgemaakte fout zie je bij erfrecht en woning?',antwoord:`Klanten denken vaak dat alles automatisch goed geregeld is. Bij samenwoners en samengestelde gezinnen is dat zelden zo. Vraag naar testament, samenlevingscontract en begunstigingen. Leg de bespreking vast.`,tags:['erfrecht','veelgemaakte fouten','testament'],bron:''},
 {id:'dgx-220',thema:'doelgroepen',vraag:'Wat als de langstlevende wil verhuizen terwijl kinderen een vordering hebben?',antwoord:`De vordering van de kinderen blijft bestaan en is meestal niet direct opeisbaar. Wel kan de verhuizing de waarde van de vordering of de boedel beïnvloeden. Controleer het testament op voorwaarden. Verwijs voor maatwerk naar een notaris.`,tags:['erfrecht','langstlevende','verhuizing'],bron:''},
 {id:'dgx-221',thema:'doelgroepen',vraag:'Waarom vraag je naar een testament bij een hypotheekadvies?',antwoord:`Het testament bepaalt mede wie de woning en de schulden krijgt. Dat beïnvloedt de risico's bij overlijden. Ook de benodigde ORV-dekking hangt hiervan af. Leg vast of er een testament is en wat er in grote lijnen in staat.`,tags:['erfrecht','testament','inventarisatie'],bron:''},
 {id:'dgx-222',thema:'doelgroepen',vraag:'Wat is de rol van de verklaring van erfrecht bij de woning?',antwoord:`Een verklaring van erfrecht toont wie de erfgenamen zijn en wie bevoegd is. Geldverstrekkers en notarissen vragen deze verklaring bij overlijden. Zonder verklaring is verkoop of overname vaak niet mogelijk. Vraag de verklaring tijdig op.`,tags:['erfrecht','verklaring van erfrecht','notaris'],bron:''},
 {id:'dgx-223',thema:'doelgroepen',vraag:'Hoe ga je om met een erfgenaam die de woning wil overnemen van mede-erfgenamen?',antwoord:`De overnemende erfgenaam moet de andere erfgenamen uitkopen. De financiering daarvan wordt getoetst als nieuwe hypotheek. Gaat de erfgenaam er wonen, dan geldt de aflossingseis voor nieuwe eigenwoningschuld. Vraag een taxatie en de verdelingsafspraken op.`,tags:['erfrecht','overname','mede-erfgenamen'],bron:'Wet IB 2001'},
 {id:'dgx-224',thema:'doelgroepen',vraag:'Wat speelt bij een restschuld in een nalatenschap?',antwoord:`Als de woning minder waard is dan de hypotheek, kan een restschuld in de nalatenschap ontstaan. Erfgenamen kunnen dan beter beneficiair aanvaarden. Bespreek dit met de notaris. Leg de bespreking vast.`,tags:['erfrecht','restschuld','beneficiair aanvaarden'],bron:''},
 {id:'dgx-225',thema:'doelgroepen',vraag:'Wat is een vruchtgebruiktestament?',antwoord:`Bij een vruchtgebruiktestament krijgen de kinderen de goederen en de langstlevende het vruchtgebruik. De langstlevende mag de woning gebruiken. Dit heeft andere fiscale en juridische gevolgen dan de wettelijke verdeling. Verwijs voor maatwerk naar een notaris en een fiscalist.`,tags:['erfrecht','vruchtgebruik','testament'],bron:''},
 {id:'dgx-226',thema:'doelgroepen',vraag:'Waarom bespreek je de kosten van kinderen in het adviesgesprek?',antwoord:`Kinderen beïnvloeden de bestedingsruimte van een huishouden. Denk aan kinderopvang, onderwijs en vrije tijd. Bespreek dit naast de maximale hypotheek. Leg vast dat het budget is besproken.`,tags:['kinderen','budget','betaalbaarheid'],bron:''},
 {id:'dgx-227',thema:'doelgroepen',vraag:'Wanneer heeft een nabestaande recht op een Anw-uitkering?',antwoord:`Een nabestaande kan onder meer recht hebben als er een kind jonger dan 18 jaar is. Ook bij voldoende arbeidsongeschiktheid kan er recht zijn. De uitkering is inkomensafhankelijk. Verwijs voor de actuele voorwaarden naar de SVB.`,tags:['kinderen','Anw','nabestaanden'],bron:'SVB'},
 {id:'dgx-228',thema:'doelgroepen',vraag:'Waarom is een wezenpensioen relevant bij advies?',antwoord:`Een wezenpensioen kan inkomen geven voor kinderen na overlijden van een ouder. De hoogte en duur hangen af van de pensioenregeling. Vraag het pensioenoverzicht op. Neem dit mee in de berekening van de ORV-behoefte.`,tags:['kinderen','wezenpensioen','overlijden'],bron:''},
 {id:'dgx-229',thema:'doelgroepen',vraag:'Wat is nodig als een minderjarig kind erfgenaam is van een woning?',antwoord:`Voor bepaalde handelingen met het vermogen van een minderjarige is toestemming van de kantonrechter nodig. Denk aan de verkoop van een woning. Dit kan de afwikkeling vertragen. Verwijs naar een notaris voor de procedure.`,tags:['kinderen','minderjarige','kantonrechter'],bron:'Burgerlijk Wetboek'},
 {id:'dgx-230',thema:'doelgroepen',vraag:'Waar let je op als ouders een woning kopen voor een studerend kind?',antwoord:`Als ouders eigenaar zijn en het kind er woont, is het voor de ouders geen eigen woning. De woning valt dan bij de ouders in box 3. Spreek een zakelijke huur af als het kind huur betaalt. Controleer de voorwaarden van de geldverstrekker over verhuur aan familie.`,tags:['kinderen','studentenwoning','box 3'],bron:'Wet IB 2001'},
 {id:'dgx-231',thema:'doelgroepen',vraag:'Welk risico loopt een ouder die borg staat voor een kind?',antwoord:`Als het kind niet betaalt, kan de geldverstrekker de ouder aanspreken. Dat kan het vermogen en de leenruimte van de ouder beïnvloeden. Bespreek dit risico uitgebreid. Leg vast dat de ouder dit begrijpt.`,tags:['kinderen','borgstelling','ouders'],bron:''},
 {id:'dgx-232',thema:'doelgroepen',vraag:'Kan een ouder die meetekent maar geen eigenaar is rente aftrekken?',antwoord:`Nee, een ouder die alleen schuldenaar is en niet in de woning woont, heeft geen eigen woning. De rente is voor die ouder dus niet aftrekbaar. Het kind kan aftrek hebben als het eigenaar is en er woont. Leg de rollen vast.`,tags:['kinderen','meetekenen','renteaftrek'],bron:'Wet IB 2001'},
 {id:'dgx-233',thema:'doelgroepen',vraag:'Wat is de eenmalig verhoogde schenkingsvrijstelling voor kinderen?',antwoord:`Ouders kunnen eenmalig een hoger bedrag belastingvrij schenken aan een kind tussen 18 en 40 jaar. Deze vrijstelling staat los van de afgeschafte vrijstelling voor de eigen woning. Verwijs voor het actuele bedrag naar de Belastingdienst. Controleer of de vrijstelling al is gebruikt.`,tags:['kinderen','schenking','vrijstelling'],bron:'Successiewet 1956'},
 {id:'dgx-235',thema:'doelgroepen',vraag:'Hoe bespreek je minder werken na de geboorte van een kind?',antwoord:`Veel ouders gaan na de komst van een kind minder werken. Dat verlaagt het inkomen terwijl de lasten blijven. Bereken de betaalbaarheid bij een lager inkomen. Leg het scenario en de keuze vast.`,tags:['kinderen','minder werken','scenario'],bron:''},
 {id:'dgx-236',thema:'doelgroepen',vraag:'Telt kinderbijslag mee als inkomen in de toetsing?',antwoord:`Kinderbijslag en vergelijkbare toeslagen tellen meestal niet mee als toetsinkomen. Ze zijn bedoeld voor de kosten van kinderen. Controleer de voorwaarden van de geldverstrekker. Leg vast welk inkomen is gebruikt.`,tags:['kinderen','kinderbijslag','toetsinkomen'],bron:''},
 {id:'dgx-238',thema:'doelgroepen',vraag:'Waarom is voogdij in een testament belangrijk?',antwoord:`Met een testament kunnen ouders een voogd voor minderjarige kinderen aanwijzen. Zonder testament beslist de rechter. Dit raakt indirect ook de woning en de nalatenschap. Wijs ouders op dit punt.`,tags:['kinderen','voogdij','testament'],bron:'Burgerlijk Wetboek'},
 {id:'dgx-239',thema:'doelgroepen',vraag:'Hoe bescherm je het erfdeel van jonge kinderen?',antwoord:`Ouders kunnen in een testament bewind instellen tot een bepaalde leeftijd. Een bewindvoerder beheert dan het vermogen. Dit voorkomt dat jonge kinderen direct over een grote som beschikken. Verwijs voor maatwerk naar een notaris.`,tags:['kinderen','bewind','testament'],bron:''},
 {id:'dgx-240',thema:'doelgroepen',vraag:'Waar let je op als ouders en kind samen een woning kopen?',antwoord:`Ouders en kind worden mede-eigenaar en meestal hoofdelijk aansprakelijk. Voor de ouders is het deel geen eigen woning als zij er niet wonen. Leg afspraken over gebruik, kosten en verkoop notarieel vast. Controleer de voorwaarden van de geldverstrekker.`,tags:['kinderen','mede-eigendom','ouders'],bron:''},
 {id:'dgx-241',thema:'doelgroepen',vraag:'Wat als ouders een woning aan een kind verhuren?',antwoord:`De huur moet zakelijk zijn om discussie met de Belastingdienst te voorkomen. De woning valt voor de ouders in box 3. Controleer of de geldverstrekker toestemming geeft voor verhuur. Leg de huurafspraken schriftelijk vast.`,tags:['kinderen','verhuur','box 3'],bron:''},
 {id:'dgx-242',thema:'doelgroepen',vraag:'Kan een grootouder een familiehypotheek aan een kleinkind verstrekken?',antwoord:`Ja, dat kan onder dezelfde voorwaarden als een lening van ouders. De lening moet zakelijk zijn en annuïtair of lineair in 360 maanden worden afgelost voor renteaftrek. Het kleinkind vermeldt de gegevens in de aangifte. Bespreek ook de gevolgen bij overlijden van de grootouder.`,tags:['kinderen','familiehypotheek','grootouders'],bron:'Wet IB 2001'},
 {id:'dgx-243',thema:'doelgroepen',vraag:'Hoe neem je kinderen mee in de risicoanalyse bij overlijden?',antwoord:`Bij overlijden van een ouder blijft vaak de zorg voor kinderen bij de langstlevende. Dat kan minder werken en hogere kosten betekenen. Neem dit mee in de berekening van de ORV-behoefte. Leg de uitgangspunten vast.`,tags:['kinderen','overlijden','ORV'],bron:''},
 {id:'dgx-244',thema:'doelgroepen',vraag:'Welke veelgemaakte fout zie je bij gezinnen met jonge kinderen?',antwoord:`Ouders hebben vaak geen testament en geen passende ORV. Ook wordt minder werken niet meegenomen in de berekening. Bespreek deze punten actief. Leg vast welke acties de klant onderneemt.`,tags:['kinderen','veelgemaakte fouten','testament'],bron:''},
 {id:'dgx-245',thema:'doelgroepen',vraag:'Waar let je op als een kind langdurig zorg nodig heeft?',antwoord:`Zorg voor een kind kan invloed hebben op inkomen en uitgaven. Een ouder kan minder gaan werken. Ook kan de woning aanpassingen nodig hebben. Neem dit mee in de betaalbaarheid en leg het vast.`,tags:['kinderen','zorg','betaalbaarheid'],bron:''},
 {id:'dgx-246',thema:'doelgroepen',vraag:'Wat als een kind een deel van de woning van de ouders overneemt?',antwoord:`Bij overname van een aandeel kan overdrachtsbelasting gelden. Het kind wordt mede-eigenaar en schuldenaar voor dat deel. Gaat het kind er wonen, dan kan het eigen woning zijn. Laat de situatie notarieel en fiscaal toetsen.`,tags:['kinderen','aandeel woning','overdrachtsbelasting'],bron:''},
 {id:'dgx-247',thema:'doelgroepen',vraag:'Hoe documenteer je een gift van ouders aan een kind voor verbouwing?',antwoord:`Leg het bedrag, de datum en het doel vast. Vraag een schenkingsakte of overeenkomst op. Bewaar het bankafschrift van de overboeking. Verwijs voor de aangifte schenkbelasting naar de Belastingdienst.`,tags:['kinderen','schenking','dossier'],bron:''},
 {id:'dgx-248',thema:'doelgroepen',vraag:'Wat als een kind met schulden in de woning van de ouders woont?',antwoord:`De schulden van het kind raken in principe de ouders niet. Wel kan het kind niet zomaar meetekenen voor een nieuwe financiering. Bespreek of het kind verhuist of meebetaalt. Leg afspraken schriftelijk vast.`,tags:['kinderen','schulden','inwonend'],bron:''},
 {id:'dgx-249',thema:'doelgroepen',vraag:'Wat betekent een huwelijk met kinderen uit een eerdere relatie voor de woning?',antwoord:`Bij de wettelijke verdeling krijgt de nieuwe echtgenoot de woning en hebben alle kinderen een vordering. Kinderen uit de eerdere relatie moeten dan wachten op het overlijden van de stiefouder. Zij kunnen in bepaalde situaties wilsrechten inroepen. Verwijs voor een passend testament naar een notaris.`,tags:['kinderen','samengesteld gezin','wettelijke verdeling'],bron:'Burgerlijk Wetboek'},
 {id:'dgx-250',thema:'doelgroepen',vraag:'Wat leg je vast over kinderen in het klantprofiel?',antwoord:`Leg het aantal kinderen, hun leeftijd en eventuele zorgbehoefte vast. Noteer ook kinderalimentatie en afspraken uit een ouderschapsplan. Deze gegevens bepalen mede de risico's bij overlijden en arbeidsongeschiktheid. Werk het profiel bij als de situatie verandert.`,tags:['kinderen','klantprofiel','dossier'],bron:''}
]);
